def copy_parameter_structure(value):
    if isinstance(value, dict):
        return {key: copy_parameter_structure(v) for (key, v) in value.items()}
    if isinstance(value, list):
        _tr_cf17_container_1 = []
        _tr_cf17_bound_2 = None
        try:
            for _tr_cf17_bound_2 in value:
                _tr_cf17_container_1.append(copy_parameter_structure(_tr_cf17_bound_2))
            return _tr_cf17_container_1
        finally:
            del _tr_cf17_container_1, _tr_cf17_bound_2
    if isinstance(value, tuple):
        _tr_cf17_container_3 = []
        _tr_cf17_bound_4 = None
        try:
            for _tr_cf17_bound_4 in value:
                _tr_cf17_container_3.append(copy_parameter_structure(_tr_cf17_bound_4))
            return tuple(_tr_cf17_container_3)
        finally:
            del _tr_cf17_container_3, _tr_cf17_bound_4
    return value



def parameter_defaults():
    return {name: copy_parameter_structure(spec['default']) for (name, spec) in PARAMETER_REGISTRY.items()}


