    _kz_reset_routes()
    _kz_sync_decode()
    _KV_OUTPUT_GRID = fnp.asarray(((_WINOGRAD_OUTPUT[0], _WINOGRAD_OUTPUT[1]), (_WINOGRAD_OUTPUT[2], _WINOGRAD_OUTPUT[3])), dtype=fnp.float32)
    _tr_cf17_container_1 = []
    _tr_cf17_bound_2 = None
