def _kv_r48_matmul(left, right, levels, threshold, schedule):
    """One owned rank48 encoding, one batched child, owned final destinations."""
    _ops5_pub_empty = fnp.empty
    _ops5_pub_split = fnp.split
    _ops5_pub_unstack = fnp.unstack
    if levels < 2 or min(left.shape[-2:] + right.shape[-1:]) <= threshold:
        return _winograd_matmul(left, right, levels, threshold, schedule)
    if any((v % 4 for v in left.shape[-2:] + right.shape[-1:])):
        return _winograd_matmul(left, right, levels, threshold, schedule)
    _tr_cf17_container_1 = []
    _tr_cf17_bound_2 = _tr_cf17_bound_3 = None
    try:
        for _tr_cf17_bound_2 in _ops5_pub_split(left, 4, axis=-2):
            for _tr_cf17_bound_3 in _ops5_pub_split(_tr_cf17_bound_2, 4, axis=-1):
                _tr_cf17_container_1.append(_tr_cf17_bound_3)
        aa = tuple(_tr_cf17_container_1)
    finally:
        del _tr_cf17_container_1, _tr_cf17_bound_2, _tr_cf17_bound_3
    _tr_cf17_container_4 = []
    _tr_cf17_bound_5 = _tr_cf17_bound_6 = None
    try:
        for _tr_cf17_bound_5 in _ops5_pub_split(right, 4, axis=-2):
            for _tr_cf17_bound_6 in _ops5_pub_split(_tr_cf17_bound_5, 4, axis=-1):
                _tr_cf17_container_4.append(_tr_cf17_bound_6)
        bb = tuple(_tr_cf17_container_4)
    finally:
        del _tr_cf17_container_4, _tr_cf17_bound_5, _tr_cf17_bound_6
    encoded_a = _ops5_pub_empty(left.shape[:-2] + (48, left.shape[-2] // 4, left.shape[-1] // 4), dtype=left.dtype)
    encoded_b = _ops5_pub_empty(right.shape[:-2] + (48, right.shape[-2] // 4, right.shape[-1] // 4), dtype=right.dtype)
    _k48_r48_l_out(aa, tuple(_ops5_pub_unstack(encoded_a, axis=-3)), fnp)
    _k48_r48_r_out(bb, tuple(_ops5_pub_unstack(encoded_b, axis=-3)), fnp)
    products = _winograd_matmul(encoded_a, encoded_b, levels - 2, threshold, schedule)
    result = _ops5_pub_empty(products.shape[:-3] + (left.shape[-2], right.shape[-1]), dtype=products.dtype)
    _tr_cf17_container_7 = []
    _tr_cf17_bound_8 = _tr_cf17_bound_9 = None
    try:
        for _tr_cf17_bound_8 in _ops5_pub_split(result, 4, axis=-2):
            for _tr_cf17_bound_9 in _ops5_pub_split(_tr_cf17_bound_8, 4, axis=-1):
                _tr_cf17_container_7.append(_tr_cf17_bound_9)
        outputs = tuple(_tr_cf17_container_7)
    finally:
        del _tr_cf17_container_7, _tr_cf17_bound_8, _tr_cf17_bound_9
    _k48_r48_p_out(tuple(_ops5_pub_unstack(products, axis=-3)), outputs, fnp)
    return result

def _kv_r48_eligible(m, k, n, batch, depth):
    mode = int(KERNEL_CONFIG.get('kv_r48', 0))
    minimum = int(KERNEL_CONFIG.get('kv_r48_min', 128))
    if mode == 0 or batch != 1 or depth < 2 or (min(m, k, n) < minimum) or (m * k * n < int(KERNEL_CONFIG.get('kv_r48_min_work', 0))):
        return False
    if mode == 1:
        return k >= 4 * max(m, n)
    if mode == 2:
        return n >= 4 * max(m, k)
    if mode == 3:
        return max(k, n) >= 4 * m
    return True

def _kv_decode_packed(products, layout, bank=None):
    _ops5_pub_add = fnp.add
    _ops5_pub_subtract = fnp.subtract
    (p1, p2, p3, p4, p5, p6, p7) = products
    axis = -(len(layout) + 3)
    if bank is not None and int(KERNEL_CONFIG.get('kv_recycle_packed_output', 0)):
        common = _ops5_pub_add(p1, p6, out=p6)
        lower = _ops5_pub_add(common, p7, out=p7)
        _ops5_pub_add(p1, p2, out=p2)
        upper = _ops5_pub_add(common, p5, out=p6)
        _ops5_pub_add(lower, p5, out=p1)
        _ops5_pub_add(upper, p3, out=p3)
        _ops5_pub_subtract(lower, p4, out=p4)
        position = len(bank.shape) + axis
        selector = (slice(None),) * position + (slice(0, 4),) + (slice(None),) * (len(bank.shape) - position - 1)
        return (bank[selector], (-2,) + layout)
    stack_limit = int(KERNEL_CONFIG.get('kv_packed_stack_elements', 0))
    if stack_limit > 0 and math.prod(p1.shape) <= stack_limit:
        a = _ops5_pub_add(p1, p2, out=p2)
        common = _ops5_pub_add(p1, p6, out=p6)
        lower = _ops5_pub_add(common, p7, out=p7)
        d = _ops5_pub_add(lower, p5, out=p1)
        upper = _ops5_pub_add(common, p5, out=p5)
        b = _ops5_pub_add(upper, p3, out=p3)
        c = _ops5_pub_subtract(lower, p4, out=p4)
        return (fnp.stack((c, d, a, b), axis=axis), (-2,) + layout)
    prefix = p1.shape[:-(len(layout) + 2)]
    tail = p1.shape[-(len(layout) + 2):]
    result = fnp.empty(prefix + (4,) + tail, dtype=p1.dtype)
    (c, d, a, b) = fnp.unstack(result, axis=axis)
    _ops5_pub_add(p1, p2, out=a)
    common = _ops5_pub_add(p1, p6, out=p6)
    lower = _ops5_pub_add(common, p7, out=p7)
    _ops5_pub_add(lower, p5, out=d)
    upper = _ops5_pub_add(common, p5, out=p5)
    _ops5_pub_add(upper, p3, out=b)
    _ops5_pub_subtract(lower, p4, out=c)
    return (result, (-2,) + layout)

def _kv_packed_leaf(left, right, levels):
    aa = _kv_leaf_encode(left, True, levels)
    bb = _kv_leaf_encode(right, False, levels)
    value = aa @ bb
    layout = ()
    for stage in range(levels):
        parts = fnp.unstack(value, axis=-(len(layout) + 3))
        order = (3, 0, 1, 2, 4, 5, 6)
        _tr_cf17_container_1 = []
        _tr_cf17_bound_2 = None
        try:
            for _tr_cf17_bound_2 in range(7):
                _tr_cf17_container_1.append(parts[order.index(_tr_cf17_bound_2)])
            products = tuple(_tr_cf17_container_1)
        finally:
            del _tr_cf17_container_1, _tr_cf17_bound_2
        (value, layout) = _kv_decode_packed(products, layout, value)
    return (value, layout)

def _kv_packed_matmul(left, right, levels, threshold, schedule):
    (rows, inner) = left.shape[-2:]
    columns = right.shape[-1]
    if levels <= 0 or min(rows, inner, columns) <= threshold or rows % 2 or inner % 2 or columns % 2:
        return (left @ right, ())
    (caps, leaf, input_threshold, output_threshold, separable_threshold, decoder_price) = schedule
    three_limit = int(KERNEL_CONFIG.get('kw_three_leaf_elements', 0))
    if levels == 3 and three_limit > 0 and (not (rows % 8 or inner % 8 or columns % 8)):
        elements = max(math.prod(left.shape), math.prod(right.shape), _matmul_batch_size(left, right) * rows * columns) // 64
        if elements <= three_limit:
            return _kv_packed_leaf(left, right, levels)
    one_limit = int(KERNEL_CONFIG.get('kw_one_level_elements', 0))
    if levels == 1 and one_limit > 0:
        elements = max(math.prod(left.shape), math.prod(right.shape), _matmul_batch_size(left, right) * rows * columns) // 4
        if elements <= one_limit:
            return _kv_packed_leaf(left, right, levels)
    if levels == 2 and separable_threshold > 0 and (not (rows % 4 or inner % 4 or columns % 4)):
        elements = max(math.prod(left.shape), math.prod(right.shape), _matmul_batch_size(left, right) * rows * columns) // 16
        if elements <= separable_threshold:
            return _kv_packed_leaf(left, right, levels)
    (a11, a12, a21, a22) = _quarters(left)
    (b11, b12, b21, b22) = _quarters(right)
    (m, k, n) = (rows // 2, inner // 2, columns // 2)
    elements = _matmul_batch_size(left, right) * max(m * k, k * n, m * n)
    chunk = max(1, min(7, caps[min(levels, 6) - 1] // max(elements, 1)))
    if levels <= int(leaf):
        chunk = 1
        limit = int(KERNEL_CONFIG.get('kw_leaf_pack_elements', 0))
        if levels == 1 and limit > 0 and (elements <= limit):
            chunk = max(1, min(7, caps[min(levels, 6) - 1] // max(elements, 1)))
    lp = {0: a11, 1: a12, 3: a22}
    ls = {4: ('+', a21, a22), 5: ('-', 4, a11), 6: ('-', a11, a21), 2: ('-', a12, 5)}
    rp = {0: b11, 1: b21, 2: b22}
    rs = {4: ('-', b12, b11), 5: ('-', b22, 4), 6: ('-', b22, b12), 3: ('-', 5, b21)}
    (lc, rc) = ({}, {})
    products = [None] * 7
    order = (3, 0, 1, 2, 4, 5, 6)
    layout = None
    bank = None
    for start in range(0, 7, chunk):
        keys = order[start:start + chunk]
        if len(keys) == 1:
            key = keys[0]
            aa = lp[key] if key in lp else _winograd_sum(key, ls, lc)
            bb = rp[key] if key in rp else _winograd_sum(key, rs, rc)
            (products[key], child_layout) = _kv_packed_matmul(aa, bb, levels - 1, threshold, schedule)
        else:
            counts = _WINOGRAD_GROUP_COUNTS[chunk, start]
            aa = _winograd_slab(lp, ls, keys, lc, left, input_threshold, counts[0])
            bb = _winograd_slab(rp, rs, keys, rc, right, input_threshold, counts[1])
            (packed, child_layout) = _kv_packed_matmul(aa, bb, levels - 1, threshold, schedule)
            if len(keys) == 7:
                bank = packed
            for (key, part) in zip(keys, fnp.unstack(packed, axis=-(len(child_layout) + 3))):
                products[key] = part
        if layout is None:
            layout = child_layout
        elif layout != child_layout:
            raise ValueError('Inconsistent packed child layout')
    return _kv_decode_packed(products, layout, bank)

def _kv_unpack_packed(value, layout):
    if not layout:
        return value
    prefix = value.shape[:-(len(layout) + 2)]
    (m, n) = value.shape[-2:]
    _tr_cf17_container_1 = []
    _tr_cf17_bound_2 = _tr_cf17_bound_3 = None
    try:
        for _tr_cf17_bound_2 in layout:
            for _tr_cf17_bound_3 in (abs(_tr_cf17_bound_2), abs(_tr_cf17_bound_2)):
                _tr_cf17_container_1.append(_tr_cf17_bound_3)
        bits = tuple(_tr_cf17_container_1)
    finally:
        del _tr_cf17_container_1, _tr_cf17_bound_2, _tr_cf17_bound_3
    value = fnp.reshape(value, prefix + bits + (m, n), copy=False)
    b = len(prefix)
    depth = len(layout)
    if any((radix < 0 for radix in layout)):
        selector = [slice(None)] * len(value.shape)
        for (i, radix) in enumerate(layout):
            if radix < 0:
                selector[b + 2 * i] = slice(None, None, -1)
        value = value[tuple(selector)]
    axes = tuple(range(b)) + tuple((b + 2 * i for i in range(depth))) + (b + 2 * depth,) + tuple((b + 2 * i + 1 for i in range(depth))) + (b + 2 * depth + 1,)
    value = fnp.transpose(value, axes)
    divisor = math.prod((abs(radix) for radix in layout))
    return fnp.reshape(value, prefix + (m * divisor, n * divisor), copy=True)

def _kv_r48_packed(left, right, levels, threshold, schedule):
    _ops5_pub_empty = fnp.empty
    _ops5_pub_split = fnp.split
    _ops5_pub_unstack = fnp.unstack
    if levels < 2 or min(left.shape[-2:] + right.shape[-1:]) <= threshold or any((v % 4 for v in left.shape[-2:] + right.shape[-1:])):
        return _kv_packed_matmul(left, right, levels, threshold, schedule)
    _tr_cf17_container_1 = []
    _tr_cf17_bound_2 = _tr_cf17_bound_3 = None
    try:
        for _tr_cf17_bound_2 in _ops5_pub_split(left, 4, axis=-2):
            for _tr_cf17_bound_3 in _ops5_pub_split(_tr_cf17_bound_2, 4, axis=-1):
                _tr_cf17_container_1.append(_tr_cf17_bound_3)
        aa = tuple(_tr_cf17_container_1)
    finally:
        del _tr_cf17_container_1, _tr_cf17_bound_2, _tr_cf17_bound_3
    _tr_cf17_container_4 = []
    _tr_cf17_bound_5 = _tr_cf17_bound_6 = None
    try:
        for _tr_cf17_bound_5 in _ops5_pub_split(right, 4, axis=-2):
            for _tr_cf17_bound_6 in _ops5_pub_split(_tr_cf17_bound_5, 4, axis=-1):
                _tr_cf17_container_4.append(_tr_cf17_bound_6)
        bb = tuple(_tr_cf17_container_4)
    finally:
        del _tr_cf17_container_4, _tr_cf17_bound_5, _tr_cf17_bound_6
    encoded_a = _ops5_pub_empty(left.shape[:-2] + (48, left.shape[-2] // 4, left.shape[-1] // 4), dtype=left.dtype)
    encoded_b = _ops5_pub_empty(right.shape[:-2] + (48, right.shape[-2] // 4, right.shape[-1] // 4), dtype=right.dtype)
    _k48_r48_l_out(aa, tuple(_ops5_pub_unstack(encoded_a, axis=-3)), fnp)
    _k48_r48_r_out(bb, tuple(_ops5_pub_unstack(encoded_b, axis=-3)), fnp)
    (products, layout) = _kv_packed_matmul(encoded_a, encoded_b, levels - 2, threshold, schedule)
    axis = -(len(layout) + 3)
    prefix = products.shape[:-(len(layout) + 3)]
    tail = products.shape[-(len(layout) + 2):]
    result = _ops5_pub_empty(prefix + (16,) + tail, dtype=products.dtype)
    _k48_r48_p_out(tuple(_ops5_pub_unstack(products, axis=axis)), tuple(_ops5_pub_unstack(result, axis=axis)), fnp)
    return (result, (4,) + layout)

def _kv_packed_root(left, right, levels, threshold, schedule):
    minimum = int(KERNEL_CONFIG.get('kv_packed_depth_min', 0))
    if levels < minimum:
        return _winograd_matmul(left, _kp_ready(right), levels, threshold, schedule)
    if _kz_eligible(left.shape[-2:] + right.shape[-1:], levels, threshold):
        work = _matmul_batch_size(left, right) * math.prod(left.shape[-2:]) * right.shape[-1]
        return _kz_matmul(left, right, _kz_schemes(levels, work, 1))
    (value, layout) = _kv_packed_matmul(left, _kp_ready(right), levels, threshold, schedule)
    return _kv_unpack_packed(value, layout)

def _kv_r48_packed_root(left, right, levels, threshold, schedule):
    minimum = int(KERNEL_CONFIG.get('kv_packed_depth_min', 0))
    if levels < minimum:
        return _kv_r48_matmul(left, right, levels, threshold, schedule)
    if _kz_eligible(left.shape[-2:] + right.shape[-1:], levels, threshold):
        work = _matmul_batch_size(left, right) * math.prod(left.shape[-2:]) * right.shape[-1]
        return _kz_r48_matmul(left, right, _kz_schemes(levels, work, 2))
    (value, layout) = _kv_r48_packed(left, right, levels, threshold, schedule)
    return _kv_unpack_packed(value, layout)

def _kv_leaf_encode(matrix, is_left, levels):
    value = matrix
    order = (3, 0, 1, 2, 4, 5, 6)
    for stage in range(levels):
        (a, b, c, d) = _quarters(value)
        if is_left:
            plain = {0: a, 1: b, 3: d}
            sums = {4: ('+', c, d), 5: ('-', 4, a), 6: ('-', a, c), 2: ('-', b, 5)}
        else:
            plain = {0: a, 1: c, 2: d}
            sums = {4: ('-', b, a), 5: ('-', d, 4), 6: ('-', d, b), 3: ('-', 5, c)}
        value = _winograd_slab(plain, sums, order, {}, value, 0, (3, 0, 1))
    return value
_KZ_LEFT = {'w': slice(1, 5), 'k': slice(2, 6), 'z': slice(2, 6)}
_KZ_RIGHT = {'w': slice(0, 4), 'k': slice(0, 4), 'z': slice(0, 4)}
_KZ_OUT = {'w': slice(1, 5), 'k': slice(2, 6), 'z': slice(3, 7)}

def _kz_sync_decode():
    """kz_fused_decode moves the w output region to slots 3..6; the region is the switch the encode and decode read."""
    _KZ_OUT['w'] = slice(3, 7) if int(KERNEL_CONFIG.get('kz_fused_decode', 0)) else slice(1, 5)
    _KZ_REGION_PLANS.clear()
    _KZ_LEVEL_PLANS.clear()
    _KZ_DECODE_PLANS.clear()

def _kz_regions(schemes, regions, below):
    """Data regions of the level axes deeper than `below`, deepest first (the outer axes)."""
    key = (schemes, id(regions), below)
    try:
        return _KZ_REGION_PLANS[key]
    except KeyError:
        _tr_cf17_container_1 = []
        _tr_cf17_bound_2 = None
        try:
            for _tr_cf17_bound_2 in range(len(schemes) - 1, below, -1):
                _tr_cf17_container_1.append(regions[schemes[_tr_cf17_bound_2]])
            value = tuple(_tr_cf17_container_1)
        finally:
            del _tr_cf17_container_1, _tr_cf17_bound_2
        _KZ_REGION_PLANS[key] = value
        return value


_KZ_BLOCKED_PLANS = {}

def _kz_blocked(matrix, schemes, right):
    """prefix+(R, C) -> prefix+(4,)*levels+(r, c), deepest level first, in each level's blocked index order."""
    plan_key = (tuple(matrix.shape), schemes, right)
    plan = _KZ_BLOCKED_PLANS.get(plan_key)
    if plan is None:
        levels = len(schemes)
        prefix = plan_key[0][:-2]
        p = len(prefix)
        (r, c) = (plan_key[0][-2] >> levels, plan_key[0][-1] >> levels)
        pairs = ()
        for level in range(levels - 1, -1, -1):
            (row, column) = (p + level, p + levels + 1 + level)
            pairs += (row, column) if (schemes[level] == 'w') == right else (column, row)
        plan = _KZ_BLOCKED_PLANS[plan_key] = (prefix + (2,) * levels + (r,) + (2,) * levels + (c,), (slice(None),) * (p + levels + 1) + (slice(None, None, -1),) * levels if right else None,
                                              tuple(range(p)) + pairs + (p + levels, p + 2 * levels + 1), prefix + (4,) * levels + (r, c))
    (split_shape, reverse, axes, blocked_shape) = plan
    split = fnp.reshape(matrix, split_shape)
    if reverse is not None:
        split = split[reverse]
    return fnp.reshape(fnp.transpose(split, axes), blocked_shape)

_SL_KZ_UNBLOCK_PLANS = {}

def _sl_kz_unblocked_original(blocked, levels):
    """prefix+(4,)*levels+(r, c), deepest level first with level index 2c+r -> prefix+(R, C)."""
    plan_key = (tuple(blocked.shape), levels)
    plan = _SL_KZ_UNBLOCK_PLANS.get(plan_key)
    if plan is None:
        prefix = plan_key[0][:-(levels + 2)]
        p = len(prefix)
        (r, c) = plan_key[0][-2:]
        axes = tuple(range(p)) + tuple(range(2 * levels + p - 1, p, -2)) + (2 * levels + p,) + tuple(range(2 * levels + p - 2, p - 1, -2)) + (2 * levels + p + 1,)
        plan = _SL_KZ_UNBLOCK_PLANS[plan_key] = (prefix + (2,) * (2 * levels) + (r, c), axes, prefix + (r << levels, c << levels))
    (split_shape, axes, matrix_shape) = plan
    split = fnp.reshape(blocked, split_shape)
    return fnp.reshape(fnp.transpose(split, axes), matrix_shape)


_SL_KZ_UNPACK_REMAINING = 0

def _sl_kz_unstack_tree(value, axis, levels):
    if levels == 0:
        return value
    parts = fnp.unstack(value, axis=axis)
    if levels == 1:
        return tuple(parts)
    _tr_cf17_container_1 = []
    _tr_cf17_bound_2 = None
    try:
        for _tr_cf17_bound_2 in parts:
            _tr_cf17_container_1.append(_sl_kz_unstack_tree(_tr_cf17_bound_2, axis, levels - 1))
        return tuple(_tr_cf17_container_1)
    finally:
        del _tr_cf17_container_1, _tr_cf17_bound_2


def _kz_unblocked(blocked, levels):
    global _SL_KZ_UNPACK_REMAINING
    extra_calls = (4 ** levels - 1) // 3 - 2
    if levels == int(KERNEL_CONFIG['sl_unpack_levels']) and _SL_KZ_UNPACK_REMAINING >= extra_calls and (math.prod(blocked.shape) >= int(KERNEL_CONFIG['sl_unpack_min_entries'])):
        _SL_KZ_UNPACK_REMAINING -= extra_calls
        axis = len(blocked.shape) - levels - 2
        tree = _sl_kz_unstack_tree(blocked, axis, levels)
        leaves = [tree]
        for _ in range(levels):
            _tr_cf17_container_1 = []
            _tr_cf17_bound_2 = _tr_cf17_bound_3 = None
            try:
                for _tr_cf17_bound_2 in leaves:
                    for _tr_cf17_bound_3 in _tr_cf17_bound_2:
                        _tr_cf17_container_1.append(_tr_cf17_bound_3)
                leaves = _tr_cf17_container_1
            finally:
                del _tr_cf17_container_1, _tr_cf17_bound_2, _tr_cf17_bound_3
        try:
            indices = _SL_KZ_GRID_INDICES[levels]
        except KeyError:
            indices = _SL_KZ_GRID_INDICES[levels] = _sl_kz_grid_indices(levels)
        return fnp.block([[leaves[index] for index in row] for row in indices])
    return _sl_kz_unblocked_original(blocked, levels)

_KZ_BASIS_PLANS = {}

def _kz_basis(blocked, base, schemes, first, right):
    """Alternative-basis change on the blocked copy for 'k' levels >= first: A21 <- A11-A21, B12 <- B12-B11."""
    plan_key = (base, schemes, first)
    plan = _KZ_BASIS_PLANS.get(plan_key)
    if plan is None:
        plan = _KZ_BASIS_PLANS[plan_key] = tuple(base + len(schemes) - 1 - level for level in range(first, len(schemes)) if schemes[level] in ('k', 'z'))
    for axis in plan:
        # One split request yields both quadrant slots (kept as size-1 axes: the same elements as blocked[..., 0] / [..., 2]).
        (first_slot, _, third_slot, _) = fnp.split(blocked, 4, axis=axis)
        fnp.subtract(first_slot, third_slot, out=first_slot if right else third_slot)

_KZ_OUTPUT_PLANS = {}

def _kz_output(blocked, base, schemes, first):
    plan_key = (base, schemes, first)
    plan = _KZ_OUTPUT_PLANS.get(plan_key)
    if plan is None:
        plan = _KZ_OUTPUT_PLANS[plan_key] = tuple(base + len(schemes) - 1 - level for level in range(first, len(schemes)) if schemes[level] == 'k')
    for axis in plan:
        q = fnp.unstack(blocked, axis=axis)
        fnp.add(q[3], q[1], out=q[3])
        fnp.subtract(q[3], q[2], out=q[2])



_KZ_LEVEL_PLANS = {}

def _kz_level_plan(base, schemes, first, right):
    """Per level of _kz_encode_levels: (region key or None, level axis, branch)."""
    regions = _KZ_RIGHT if right else _KZ_LEFT
    steps = []
    for level in range(first, len(schemes)):
        deeper = _kz_regions(schemes, regions, level)
        scheme = schemes[level]
        if right:
            branch = 0 if scheme == 'k' else (1 if _KZ_OUT['w'].start == 3 else 2) if scheme == 'w' else 3 if scheme == 'z' else 4
        else:
            branch = 5 if scheme == 'w' else 6
        steps.append(((slice(None),) * base + deeper if deeper else None, base + len(schemes) - 1 - level, branch))
    return tuple(steps)

def _kz_encode_levels(buffer, base, schemes, first, right):
    _ops5_pub_subtract = fnp.subtract
    plan_key = (base, schemes, first, right)
    plan = _KZ_LEVEL_PLANS.get(plan_key)
    if plan is None:
        plan = _KZ_LEVEL_PLANS[plan_key] = _kz_level_plan(base, schemes, first, right)
    for (key, axis, branch) in plan:
        view = buffer if key is None else buffer[key]
        if branch == 0:
            (q0, q1, q23, q45, q6) = fnp.split(view, (1, 2, 4, 6), axis=axis)
            _ops5_pub_subtract(q1, q0, out=q6)
            _ops5_pub_subtract(q6, q23, out=q45)
            continue
        q = fnp.unstack(view, axis=axis)
        if branch == 5:
            fnp.add(q[2], q[4], out=q[0])
            _ops5_pub_subtract(q[1], q[2], out=q[6])
            _ops5_pub_subtract(q[0], q[1], out=q[5])
            _ops5_pub_subtract(q[3], q[5], out=q[2])
        elif branch == 6:
            _ops5_pub_subtract(q[5], q[4], out=q[6])
            fnp.add(q[6], q[2], out=q[0])
            _ops5_pub_subtract(q[3], q[6], out=q[1])
        elif branch <= 2:
            _ops5_pub_subtract(q[2], q[0], out=q[6])
            _ops5_pub_subtract(q[0], q[1], out=q[0])
            _ops5_pub_subtract(q[2], q[0], out=q[5])
            if branch == 1:
                _ops5_pub_subtract(q[3], q[5], out=q[4])
            else:
                _ops5_pub_subtract(q[5], q[3], out=q[4])
        else:
            _ops5_pub_subtract(q[1], q[0], out=q[6])
            if branch == 3:
                _ops5_pub_subtract(q[3], q[6], out=q[5])
            else:
                _ops5_pub_subtract(q[6], q[3], out=q[5])
            _ops5_pub_subtract(q[6], q[2], out=q[4])

def _kz_encode_left(blocked, buffer, base, schemes):
    """Copy the plain bases and encode level 0 through pre-split destination views."""
    _ops5_pub_split = fnp.split
    _ops5_pub_subtract = fnp.subtract
    _kz_basis(blocked, base, schemes, 1, False)
    levels = len(schemes)
    (top, head) = (base + levels - 1, (slice(None),) * base)
    _rf_rg17_5155_1_key = (schemes, id(_KZ_LEFT), 0)
    try:
        _rf_rg17_5155_1_key_value = _KZ_REGION_PLANS[_rf_rg17_5155_1_key]
    except KeyError:
        _rf_rg17_5155_1_key_value = tuple((_KZ_LEFT[schemes[_rf_rg17_5155_1_key_level]] for _rf_rg17_5155_1_key_level in range(len(schemes) - 1, 0, -1)))
        _KZ_REGION_PLANS[_rf_rg17_5155_1_key] = _rf_rg17_5155_1_key_value
    del _rf_rg17_5155_1_key
    deeper = _rf_rg17_5155_1_key_value
    del _rf_rg17_5155_1_key_value
    a = _ops5_pub_split(blocked, 4, axis=top)
    view = buffer[head + deeper] if deeper else buffer
    if schemes[0] == 'w':
        (o0, o1, o2, o34, o5, o6) = _ops5_pub_split(view, (1, 2, 3, 5, 6), axis=top)
        fnp.copyto(o1, a[0])
        fnp.concatenate(a[2:4], axis=top, out=o34)
        fnp.add(a[1], a[3], out=o0)
        _ops5_pub_subtract(a[0], a[1], out=o6)
        _ops5_pub_subtract(o0, a[0], out=o5)
        _ops5_pub_subtract(a[2], o5, out=o2)
    else:
        (o0, o1, o23, o4, o5, o6) = _ops5_pub_split(view, (1, 2, 4, 5, 6), axis=top)
        fnp.concatenate(a[0:2], axis=top, out=o23)
        fnp.copyto(o5, a[3])
        _ops5_pub_subtract(a[0], a[2], out=o4)
        _ops5_pub_subtract(a[3], o4, out=o6)
        fnp.add(o6, a[0], out=o0)
        _ops5_pub_subtract(a[1], o6, out=o1)
    _kz_encode_levels(buffer, base, schemes, 1, False)

def _kz_encode_right(blocked, buffer, base, schemes):
    _ops5_pub_subtract = fnp.subtract
    _kz_basis(blocked, base, schemes, 1, True)
    levels = len(schemes)
    (top, head) = (base + levels - 1, (slice(None),) * base)
    _rf_rg17_5180_1_key = (schemes, id(_KZ_RIGHT), 0)
    try:
        _rf_rg17_5180_1_key_value = _KZ_REGION_PLANS[_rf_rg17_5180_1_key]
    except KeyError:
        _rf_rg17_5180_1_key_value = tuple((_KZ_RIGHT[schemes[_rf_rg17_5180_1_key_level]] for _rf_rg17_5180_1_key_level in range(len(schemes) - 1, 0, -1)))
        _KZ_REGION_PLANS[_rf_rg17_5180_1_key] = _rf_rg17_5180_1_key_value
    del _rf_rg17_5180_1_key
    deeper = _rf_rg17_5180_1_key_value
    del _rf_rg17_5180_1_key_value
    b = fnp.split(blocked, 4, axis=top)
    view = buffer[head + deeper] if deeper else buffer
    (o0, o123, o4, o5, o6) = fnp.split(view, (1, 4, 5, 6), axis=top)
    fnp.concatenate(b[1:4], axis=top, out=o123)
    if schemes[0] == 'w':
        _ops5_pub_subtract(b[2], b[0], out=o6)
        _ops5_pub_subtract(b[0], b[1], out=o0)
        _ops5_pub_subtract(b[2], o0, out=o5)
        if _KZ_OUT['w'].start == 3:
            _ops5_pub_subtract(b[3], o5, out=o4)
        else:
            _ops5_pub_subtract(o5, b[3], out=o4)
    else:
        _ops5_pub_subtract(b[0], b[2], out=o0)
        _ops5_pub_subtract(b[1], o0, out=o6)
        _ops5_pub_subtract(o6, b[3], out=o5)
        _ops5_pub_subtract(o6, b[2], out=o4)
    _kz_encode_levels(buffer, base, schemes, 1, True)

_KZ_DECODE_PLANS = {}

def _kz_decode_plan(base, schemes, direct):
    """Per level of _kz_decode, deepest first: (branch, region key or None, level axis, prebuilt slot keys)."""
    steps = []
    for level in range(len(schemes) - 1, -1, -1):
        deeper = _kz_regions(schemes, _KZ_OUT, level)
        key = (slice(None),) * base + deeper if deeper else None
        axis = base + len(schemes) - 1 - level
        head = (slice(None),) * axis
        scheme = schemes[level]
        if scheme == 'w' and _KZ_OUT['w'].start == 3:
            if direct and level == 0:
                steps.append((0, key, axis, (head + (slice(0, 1),), head + (slice(6, 0, -5),), head + (slice(6, None, -6),), head + (slice(4, 1, -2),), head + (slice(1, 3),), head + (slice(3, 4),))))
            else:
                steps.append((1, key, axis, (head + (slice(5, 2, -2),), head + (slice(6, 0, -5),), head + (slice(6, None, -6),), head + (slice(4, 1, -2),), head + (slice(4, 6),))))
        elif scheme == 'z':
            steps.append((2, key, axis, (head + (slice(6, 2, -3),),)))
        else:
            steps.append((3 if scheme == 'w' else 4, key, axis, ()))
    return tuple(steps)

def _kz_decode(products, base, schemes, dest=None):
    _ops5_pub_add = fnp.add
    _ops5_pub_split = fnp.split
    _ops5_pub_subtract = fnp.subtract
    plan_key = (base, schemes, dest is not None, _KZ_OUT['w'].start)
    plan = _KZ_DECODE_PLANS.get(plan_key)
    if plan is None:
        plan = _KZ_DECODE_PLANS[plan_key] = _kz_decode_plan(base, schemes, dest is not None)
    for (branch, key, axis, keys) in plan:
        view = products if key is None else products[key]
        if branch == 0:
            q = _ops5_pub_split(view, 7, axis=axis)
            _ops5_pub_add(q[1], q[5], out=q[5])
            _ops5_pub_add(q[1], q[3], out=dest[keys[0]])
            u3_u4 = view[keys[1]]
            _ops5_pub_add(q[5], view[keys[2]], out=u3_u4)
            _ops5_pub_add(u3_u4, view[keys[3]], out=dest[keys[4]])
            _ops5_pub_add(q[6], q[0], out=dest[keys[5]])
        elif branch == 1:
            (q0, q1, _, q5, q6) = _ops5_pub_split(view, (1, 2, 5, 6), axis=axis)
            u2_c11 = view[keys[0]]
            _ops5_pub_add(q1, u2_c11, out=u2_c11)
            u3_u4 = view[keys[1]]
            _ops5_pub_add(q5, view[keys[2]], out=u3_u4)
            _ops5_pub_add(u3_u4, view[keys[3]], out=view[keys[4]])
            _ops5_pub_add(q6, q0, out=q6)
        elif branch == 2:
            q = _ops5_pub_split(view, 7, axis=axis)
            u2_c11 = view[keys[0]]
            _ops5_pub_add(q[2], u2_c11, out=u2_c11)
            _ops5_pub_add(q[6], q[0], out=q[2])
            _ops5_pub_add(q[6], q[4], out=q[6])
            _ops5_pub_add(q[6], q[5], out=q[4])
            _ops5_pub_add(q[2], q[1], out=q[5])
            _ops5_pub_add(q[6], q[0], out=q[6])
        elif branch == 3:
            q = fnp.unstack(view, axis=axis)
            _ops5_pub_add(q[1], q[5], out=q[5])
            _ops5_pub_add(q[1], q[3], out=q[1])
            _ops5_pub_add(q[5], q[6], out=q[6])
            _ops5_pub_add(q[5], q[0], out=q[5])
            _ops5_pub_add(q[5], q[2], out=q[3])
            _ops5_pub_subtract(q[6], q[4], out=q[2])
            _ops5_pub_add(q[6], q[0], out=q[4])
        else:
            q = fnp.unstack(view, axis=axis)
            _ops5_pub_add(q[2], q[6], out=q[6])
            _ops5_pub_add(q[2], q[3], out=q[2])
            _ops5_pub_add(q[6], q[4], out=q[6])
            _ops5_pub_subtract(q[6], q[5], out=q[3])
            _ops5_pub_subtract(q[4], q[1], out=q[4])
            _ops5_pub_add(q[0], q[5], out=q[5])

def _kz_matmul(left, right, schemes):
    """Packed product with one level per scheme letter; matrix dims divisible by 2**len(schemes)."""
    if _kz_use_r48_root(left, right, schemes):
        return _kz_r48_matmul(left, _kp_ready(right), schemes)
    schemes = _ka_addition_basis(schemes, (left.shape[-2], left.shape[-1], right.shape[-1]), 1)
    levels = len(schemes)
    (m, k, n) = (left.shape[-2] >> levels, left.shape[-1] >> levels, right.shape[-1] >> levels)
    (left_prefix, right_prefix) = (left.shape[:-2], right.shape[:-2])
    encoded_left = fnp.empty(left_prefix + (7,) * levels + (m, k), dtype=left.dtype)
    _kz_encode_left(_kz_blocked(left, schemes, False), encoded_left, len(left_prefix), schemes)
    key = hf_right_cache_key(right, schemes)
    encoded_right = hf_right_cache_get(key)
    carry = None
    if encoded_right is None:
        carry = kr_carry_key(right, ('kz', schemes))
        encoded_right = kr_carry_get(carry, right)
    if encoded_right is None:
        right = _kp_ready(right)
        encoded_right = fnp.empty(right_prefix + (7,) * levels + (k, n), dtype=right.dtype)
        _kz_encode_right(_kz_blocked(right, schemes, True), encoded_right, len(right_prefix), schemes)
        hf_right_cache_put(key, encoded_right)
        kr_carry_put(carry, right, encoded_right)
    products = fnp.matmul(encoded_left, encoded_right)
    del encoded_left, encoded_right
    base = len(products.shape) - levels - 2
    _kz_decode(products, base, schemes)
    _rf_rg17_5274_1_key = (schemes, id(_KZ_OUT), -1)
    try:
        _rf_rg17_5274_1_key_value = _KZ_REGION_PLANS[_rf_rg17_5274_1_key]
    except KeyError:
        _rf_rg17_5274_1_key_value = tuple((_KZ_OUT[schemes[_rf_rg17_5274_1_key_level]] for _rf_rg17_5274_1_key_level in range(len(schemes) - 1, -1, -1)))
        _KZ_REGION_PLANS[_rf_rg17_5274_1_key] = _rf_rg17_5274_1_key_value
    del _rf_rg17_5274_1_key
    result = products[(slice(None),) * base + _rf_rg17_5274_1_key_value]
    del _rf_rg17_5274_1_key_value
    _kz_output(result, base, schemes, 0)
    return _kz_unblocked(result, levels)

def _kz_blocks16(blocked, axis, right, scheme_pair):
    """The 16 row-major 4x4 blocks (index 4*bi+bj); level-1 axis at `axis`, the level-0 axis right after it."""
    _tr_cf17_container_1 = []
    _tr_cf17_bound_2 = None
    try:
        for _tr_cf17_bound_2 in fnp.unstack(blocked, axis=axis):
            _tr_cf17_container_1.append(fnp.unstack(_tr_cf17_bound_2, axis=axis))
        planes = _tr_cf17_container_1
    finally:
        del _tr_cf17_container_1, _tr_cf17_bound_2

    def index(level, row, column):
        if right:
            column = 1 - column
        return 2 * row + column if (scheme_pair[level] == 'w') == right else 2 * column + row
    _tr_cf17_container_3 = []
    _tr_cf17_bound_4 = _tr_cf17_bound_5 = None
    try:
        for _tr_cf17_bound_4 in range(4):
            for _tr_cf17_bound_5 in range(4):
                _tr_cf17_container_3.append(planes[index(1, _tr_cf17_bound_4 & 1, _tr_cf17_bound_5 & 1)][index(0, _tr_cf17_bound_4 >> 1, _tr_cf17_bound_5 >> 1)])
        return tuple(_tr_cf17_container_3)
    finally:
        del _tr_cf17_container_3, _tr_cf17_bound_4, _tr_cf17_bound_5

def _kz_r48_matmul(left, right, schemes):
    """Rank-48 top (the first two scheme letters only order its blocks) over in-place packed levels; the 48 axis sits
    inside the level axes."""
    _ops5_pub_empty = fnp.empty
    _ops5_pub_unstack = fnp.unstack
    levels = len(schemes)
    schemes = schemes[:2] + _ka_addition_basis(schemes[2:], (left.shape[-2], left.shape[-1], right.shape[-1]), 0)
    inner = schemes[2:]
    depth = len(inner)
    (m, k, n) = (left.shape[-2] >> levels, left.shape[-1] >> levels, right.shape[-1] >> levels)
    (left_prefix, right_prefix) = (left.shape[:-2], right.shape[:-2])
    (lp, rp) = (len(left_prefix), len(right_prefix))
    (blocked_left, blocked_right) = (_kz_blocked(left, schemes, False), _kz_blocked(right, schemes, True))
    _kz_basis(blocked_left, lp, schemes, 2, False)
    _kz_basis(blocked_right, rp, schemes, 2, True)
    encoded_left = _ops5_pub_empty(left_prefix + (7,) * depth + (48,) + (m, k), dtype=left.dtype)
    encoded_right = _ops5_pub_empty(right_prefix + (7,) * depth + (48,) + (k, n), dtype=right.dtype)
    _rf_rg17_5303_1_key = (inner, id(_KZ_LEFT), -1)
    try:
        _rf_rg17_5303_1_key_value = _KZ_REGION_PLANS[_rf_rg17_5303_1_key]
    except KeyError:
        _rf_rg17_5303_1_key_value = tuple((_KZ_LEFT[inner[_rf_rg17_5303_1_key_level]] for _rf_rg17_5303_1_key_level in range(len(inner) - 1, -1, -1)))
        _KZ_REGION_PLANS[_rf_rg17_5303_1_key] = _rf_rg17_5303_1_key_value
    del _rf_rg17_5303_1_key
    _rf_rg17_5303_2_key = (inner, id(_KZ_RIGHT), -1)
    try:
        _rf_rg17_5303_2_key_value = _KZ_REGION_PLANS[_rf_rg17_5303_2_key]
    except KeyError:
        _rf_rg17_5303_2_key_value = tuple((_KZ_RIGHT[inner[_rf_rg17_5303_2_key_level]] for _rf_rg17_5303_2_key_level in range(len(inner) - 1, -1, -1)))
        _KZ_REGION_PLANS[_rf_rg17_5303_2_key] = _rf_rg17_5303_2_key_value
    del _rf_rg17_5303_2_key
    (left_regions, right_regions) = (_rf_rg17_5303_1_key_value, _rf_rg17_5303_2_key_value)
    del _rf_rg17_5303_1_key_value, _rf_rg17_5303_2_key_value
    _k48_r48_l_out(_kz_blocks16(blocked_left, lp + depth, False, schemes[:2]), tuple(_ops5_pub_unstack(encoded_left[(slice(None),) * lp + left_regions] if depth else encoded_left, axis=lp + depth)), fnp)
    _k48_r48_r_out(_kz_blocks16(blocked_right, rp + depth, True, schemes[:2]), tuple(_ops5_pub_unstack(encoded_right[(slice(None),) * rp + right_regions] if depth else encoded_right, axis=rp + depth)), fnp)
    del blocked_left, blocked_right
    _kz_encode_levels(encoded_left, lp, inner, 0, False)
    _kz_encode_levels(encoded_right, rp, inner, 0, True)
    products = fnp.matmul(encoded_left, encoded_right)
    del encoded_left, encoded_right
    base = len(products.shape) - depth - 3
    _kz_decode(products, base, inner)
    result = _ops5_pub_empty(products.shape[:base] + (4,) * depth + (4, 4) + (m, n), dtype=products.dtype)
    _rf_rg17_5315_1_key = (inner, id(_KZ_OUT), -1)
    try:
        _rf_rg17_5315_1_key_value = _KZ_REGION_PLANS[_rf_rg17_5315_1_key]
    except KeyError:
        _rf_rg17_5315_1_key_value = tuple((_KZ_OUT[inner[_rf_rg17_5315_1_key_level]] for _rf_rg17_5315_1_key_level in range(len(inner) - 1, -1, -1)))
        _KZ_REGION_PLANS[_rf_rg17_5315_1_key] = _rf_rg17_5315_1_key_value
    del _rf_rg17_5315_1_key
    out_regions = _rf_rg17_5315_1_key_value
    del _rf_rg17_5315_1_key_value
    _k48_r48_p_out(tuple(_ops5_pub_unstack(products[(slice(None),) * base + out_regions] if depth else products, axis=base + depth)), _kz_blocks16(result, base + depth, False, 'ww'), fnp)
    del products
    _kz_output(result, base, schemes, 2)
    return _kz_unblocked(result, levels)

def _kz_eligible(dims, levels, threshold):
    """kz_inplace_levels gate; the packed recursion must reach all `levels` (even dims above the leaf threshold)."""
    minimum = int(KERNEL_CONFIG.get('kz_inplace_levels', 0))
    return minimum > 0 and levels >= minimum and all((v % (1 << levels) == 0 for v in dims)) and (min(dims) >> levels - 1 > threshold)

def _kz_schemes(levels, work, top):
    """Winograd levels, with the deepest kz_alt_levels in the alternative basis for roots of at least
    kz_alt_min_work batch*m*k*n; the top `top` levels (rank-48 or the root) stay Winograd."""
    alt = int(KERNEL_CONFIG.get('kz_alt_levels', 0))
    if work < int(KERNEL_CONFIG.get('kz_alt_min_work', 0)):
        alt = 0
    alt = max(0, min(alt + (alt > 0 and levels >= 6 and top == 1) + (alt > 0 and levels >= 7 and top == 1), levels - top))
    return 'w' * (levels - alt) + 'k' * alt

def initialize_state(runtime, mlp):
    _fe42_sel = None
    leg_tiers = parse_tiers(PARAMS['leg_tiers'])
    if len(leg_tiers) != 1:
        raise ValueError('static package supports one nonempty leg tier')
    runtime.feed_pending.clear()
    runtime.feed_active = int(PARAMS['feed_fold']) != 0
    runtime.history_join['ctx'] = None
    width = mlp.width
    zeros_vector = fnp.zeros(width, dtype=fnp.float32)
    ones_vector = fnp.ones(width, dtype=fnp.float32)
    wick_coefficients = runtime.coefficients['wick']
    power_mix = runtime.coefficients['power_mix']
    chi_mean = chi_mean_ratio(width)
    remainder_projection = fixed_projection(runtime, width, min(width, 2))
    transport_tiers = parse_tiers(PARAMS['transport_tiers'])
    row_alive_tiers = parse_tiers(PARAMS['row_alive_tiers'])
    col_alive_tiers = parse_tiers(PARAMS['col_alive_tiers'])
    row_inverse_prev = None
    leg_level_gain = float(PARAMS['leg_level_gain'])
    final_k3_scale = float(PARAMS['final_k3_scale'])
    final_k4_scale = float(PARAMS['final_k4_scale'])
    terminal_kink_rows = min(int(PARAMS['terminal_kink_rows']), width)
    if terminal_kink_rows <= 0:
        raise ValueError('terminal_kink_rows must be positive')
    pair_kink_rows = min(int(PARAMS['pair_kink_rows']), width)
    if pair_kink_rows <= 0:
        raise ValueError('pair_kink_rows must be positive')
    carrier_terms = [('mu_var', float(PARAMS['k3_carrier_mu_var']))] if PARAMS['k3_carrier_mu_var'] != 0.0 else []
    dress_rate = float(PARAMS['k3_vertex_dress']) / 6.0
    pair_ck3 = float(PARAMS['pair_ck3'])
    cov_k3sq = float(PARAMS['cov_k3sq']) / 6.0
    cov_k3cross = float(PARAMS['cov_k3cross']) / 6.0
    t2_k3_scale = float(PARAMS['t2_k3_scale'])
    _fe34_t2 = PARAMS['t2_k3_shape']
    t2_k3_coefficients = fnp.asarray((0.25 * t2_k3_scale * _fe34_t2[0], 0.5 * t2_k3_scale * _fe34_t2[1], 0.25 * t2_k3_scale * _fe34_t2[2]), dtype=fnp.float32)
    split_pair_c3_cov = float(PARAMS['split_pair_c3_cov'])
    cov_adt3 = float(PARAMS['cov_adt3'])
    cov_weight = float(PARAMS['k4_cov_weight'])
    identity_share = 1.0 - cov_weight
    cov_frobenius_share = cov_weight * cov_weight
    identity_frobenius_share = 1.0 - cov_frobenius_share
    identity_gain = 0.0
    cov_gain = cov_weight
    mean = zeros_vector
    covariance = fnp.eye(width, dtype=fnp.float32)
    carried_gain = None
    source_path_factors = []
    source_free_u = []
    source_free_diagonals = []
    source_remainder_left = []
    source_remainder_right = []
    source_singleton_diagonals = []
    source_alive = []
    _fe10_qoff = []
    source_transport_alive = []
    k4_star_scale = float(PARAMS.get('k4_star_scale', 0.0))
    k4_22_dress = float(PARAMS.get('k4_22_dress', 0.0))
    source_k4_star_vertices = [] if k4_star_scale != 0.0 else None
    k4_family_ratios = tuple((float(PARAMS.get(key, 0.0)) / k4_star_scale for key in ('k4_d22c_scale', 'k4_d31c_scale'))) + (1.0 / k4_star_scale,) if k4_star_scale != 0.0 else (0.0, 0.0, 0.0)
