_KE_SOLO_FINALS = {id(_KZ_R20_GRAPHS[kind][2]): frozenset((node,)) for (kind, node) in (((3, 2, 4), 20), ((4, 2, 3), 15))}
_KZ_R20_TOPS = tuple(((kind, tuple((len(g[0]) + sum((1 for o in g[1] if o < 0)) + extra for (g, extra) in zip(graphs, _KZ_R20_PRICED_ROWS.get(kind, (0, 0, 0)))))) for (kind, graphs) in _KZ_R20_GRAPHS.items()))



_KZ_REGION_PLANS = {}


def _sl_kz_grid_indices(levels):
    """Map row/column bits to the depth-first order of a radix-four tree."""
    offsets = tuple(sum(((row >> shift) & 1) << (2 * (levels - 1 - shift))
                        for shift in range(levels))
                    for row in range(1 << levels))
    return tuple(tuple(row + 2 * column for column in offsets) for row in offsets)


_SL_KZ_GRID_INDICES = {levels: _sl_kz_grid_indices(levels) for levels in (4, 5)}


def _kz_compile_graph(graph):
    """Precompute immutable routing and the final reads of owned internal nodes."""
    slot = {}
    for (j, node) in enumerate(graph[1]):
        slot.setdefault(node, j)
    last_read = {}
    serial = 0
    for (op, scalar, ids, aa, bb, a_shared, b_shared) in graph[0]:
        for (node, a, b) in zip(ids, aa, bb):
            last_read[a] = serial
            last_read[b] = serial
            serial += 1
    steps = []
    serial = 0
    for (step, (op, scalar, ids, aa, bb, a_shared, b_shared)) in enumerate(graph[0]):
        instructions = []
        for (node, a, b) in zip(ids, aa, bb):
            target = slot.get(node)
            reuse = None
            if target is None:
                if a >= 0 and a not in slot and (last_read[a] == serial):
                    reuse = a
                elif b >= 0 and b not in slot and (last_read[b] == serial):
                    reuse = b
            instructions.append((node, a, b, target, reuse))
            serial += 1
        steps.append((op, tuple(instructions), graph[2][step]))
    _tr_cf17_container_1 = []
    _tr_cf17_bound_2 = _tr_cf17_bound_3 = None
    try:
        for (_tr_cf17_bound_2, _tr_cf17_bound_3) in enumerate(graph[1]):
            if _tr_cf17_bound_3 < 0:
                _tr_cf17_container_1.append((_tr_cf17_bound_2, _tr_cf17_bound_3))
        plain = tuple(_tr_cf17_container_1)
    finally:
        del _tr_cf17_container_1, _tr_cf17_bound_2, _tr_cf17_bound_3
    _tr_cf17_container_4 = []
    _tr_cf17_bound_5 = _tr_cf17_bound_6 = None
    try:
        for (_tr_cf17_bound_5, _tr_cf17_bound_6) in enumerate(graph[1]):
            if _tr_cf17_bound_6 >= 0 and slot[_tr_cf17_bound_6] != _tr_cf17_bound_5:
                _tr_cf17_container_4.append((_tr_cf17_bound_5, _tr_cf17_bound_6))
        duplicate = tuple(_tr_cf17_container_4)
    finally:
        del _tr_cf17_container_4, _tr_cf17_bound_5, _tr_cf17_bound_6
    return (plain, tuple(steps), duplicate)


_KZ_GRAPH_PLANS = {id(graph): _kz_compile_graph(graph)
                   for family in (_KP_R40_GRAPHS, _KZ_R20_GRAPHS)
                   for graphs in family.values() for graph in graphs}


def compile_feature_plan(names):
    names = validate_features(names)
    _tr_cf17_container_1 = []
    _tr_cf17_bound_2 = _tr_cf17_bound_3 = None
    try:
        for _tr_cf17_bound_2 in ('ratio', 'matrix'):
            for _tr_cf17_bound_3 in names:
                if FEATURE_REGISTRY[_tr_cf17_bound_3]['kind'] == _tr_cf17_bound_2:
                    _tr_cf17_container_1.append(_tr_cf17_bound_3)
        ordered = tuple(_tr_cf17_container_1)
    finally:
        del _tr_cf17_container_1, _tr_cf17_bound_2, _tr_cf17_bound_3
    (ratio, matrix) = ([], [])
    offset = 0
    for name in ordered:
        spec = FEATURE_REGISTRY[name]
        width = spec['width']
        columns = tuple(range(offset, offset + width))
        (ratio if spec['kind'] == 'ratio' else matrix).append((name, spec['function'], width, columns))
        offset += width
    return (names, ordered, tuple(ratio), tuple(matrix), offset)


PAIR_KINK_ROWS_BY_LAYER = {8: 768, 9: 768, 10: 704, 4: 960, 5: 960}


def prepare_join_constants(runtime):
    """Setup-owned, read-only index and ridge operands for shared leg joins."""
    constants = {}
    if runtime.width == 1024 and runtime.depth == 16:
        for _, rank in parse_tiers(PARAMS['leg_tiers']):
            if rank < runtime.width and rank not in constants:
                drop = max(0, rank - 8)
                ids = fnp.asarray([j for j in range(rank) if j != drop], dtype=fnp.int64)
                constants[rank] = (ids, fnp.eye(rank - 1, dtype=fnp.float32))
    runtime.join_constants = constants


def hf_history_operand(part, state, start, end):
    ids = state['transport']
    indexed = state['row_inverse'] is None and ids is not None
    count = int(part.shape[0]) if ids is None else int(ids.shape[0])
    selection = ('indexed' if indexed else 'prefix', count, int(start), int(end))
    return ((part, ids if indexed else None), selection)


def _sl_kz_reset_unpack():
    """Reset the per-predict fresh-block unpack budget (called by Estimator._predict_impl after the runtime is active)."""
    global _SL_KZ_UNPACK_REMAINING
    _SL_KZ_UNPACK_REMAINING = int(KERNEL_CONFIG['sl_unpack_call_budget'])


def hf_original_fast_matmul(left, right, leg_transport=False):
    if len(left.shape) == 2 and len(right.shape) == 2 and (str(left.dtype) == 'float32') and (str(right.dtype) == 'float32'):
        route = _kz_r40_route(int(left.shape[0]), int(left.shape[1]), int(right.shape[1]))
        if route is not None:
            return _kz_r40_padded(left, right, route[0], route[1])
    orientation = int(KERNEL_CONFIG.get('kw_product_orientation', 0))
    if orientation:
        (m, k) = left.shape[-2:]
        n = right.shape[-1]
        transpose = False
        if orientation in (1, 2):
            transpose = m * int(KERNEL_CONFIG['ck_aspect_ratio']) <= min(k, n) and (orientation == 2 or _matmul_batch_size(left, right) == 1)
        elif orientation == 3:
            transpose = math.prod(right.shape) > math.prod(left.shape)
        if transpose:
            result = _kw_forward_matmul(_kw_matrix_transpose(right), _kw_matrix_transpose(left), leg_transport)
            return _kw_matrix_transpose(result)
    return _kw_forward_matmul(left, right, leg_transport)


_HF_RIGHT_CACHE = {}


_HF_RIGHT_CACHE_SIZE = [0]


_HF_RIGHT_CACHE_CONTEXT = [None]


_HF_RIGHT_CACHE_STATS = {'hits': 0, 'misses': 0, 'evictions': 0, 'peak_bytes': 0}


def hf_history_pack_tag(pairs):
    if not pairs:
        return None
    for item in pairs:
        if len(item) < 3:
            return None
    words = []
    for item in pairs:
        (refs, selection) = item[2]
        if words and len(selection) == 4 and (len(words[-1][1]) == 4):
            (prior_refs, prior_selection) = words[-1]
            same = len(refs) == len(prior_refs)
            if same:
                for (a, b) in zip(refs, prior_refs):
                    if a is not b:
                        same = False
                        break
            adjacent = same and selection[:2] == prior_selection[:2] and (prior_selection[3] == selection[2])
            if adjacent:
                words[-1] = (refs, prior_selection[:3] + (selection[3],))
                continue
        words.append((refs, selection))
    metadata = []
    references = []
    for (refs, selection) in words:
        metadata.append((tuple(map(id, refs)), selection))
        references.extend(refs)
    return (('history_pack', tuple(metadata)), tuple(references))


def hf_right_cache_key(right, schemes):
    context = _HF_RIGHT_CACHE_CONTEXT[0]
    if context is None or not context['allow'] or str(right.dtype) != 'float32':
        return None
    if int(KERNEL_CONFIG['hf_history_cache_bytes']) <= 0:
        return None
    tag = context['tag'][0]
    role = 'source' if tag[0] == 'source_pair_bank' else 'thin' if all((word[1][0] == 'transpose' for word in tag[1])) else 'history'
    policy = KERNEL_CONFIG['hf_history_cache_policy']
    if policy != 'all' and role not in (('source', 'thin') if policy == 'source_thin' else (policy,)):
        return None
    return (tag, tuple(right.shape), schemes)


def hf_right_cache_get(key):
    if key is None:
        return None
    _HF_RIGHT_CACHE_SEEN[key] = _HF_RIGHT_CACHE_SEEN.get(key, 0) + 1
    found = _HF_RIGHT_CACHE.get(key)
    refs = _HF_RIGHT_CACHE_CONTEXT[0]['tag'][1]
    if found is not None and len(found[0]) == len(refs) and _tr_same_object_references(found[0], refs):
        _HF_RIGHT_CACHE.pop(key)
        _HF_RIGHT_CACHE[key] = found
        _HF_RIGHT_CACHE_STATS['hits'] += 1
        return found[1]
    _HF_RIGHT_CACHE_STATS['misses'] += 1
    return None


def hf_right_cache_put(key, encoded):
    if key is None:
        return
    if _HF_RIGHT_CACHE_SEEN.get(key, 0) < int(KERNEL_CONFIG['hf_history_cache_warmup']):
        return
    limit = int(KERNEL_CONFIG['hf_history_cache_bytes'])
    size = 4 * math.prod(encoded.shape)
    if size > limit or size < int(KERNEL_CONFIG['hf_history_cache_min_bytes']):
        return
    previous = _HF_RIGHT_CACHE.pop(key, None)
    if previous is not None:
        _HF_RIGHT_CACHE_SIZE[0] -= previous[2]
    hf_right_cache_purge()
    while _HF_RIGHT_CACHE and _HF_RIGHT_CACHE_SIZE[0] + size > limit:
        oldest = next(iter(_HF_RIGHT_CACHE))
        removed = _HF_RIGHT_CACHE.pop(oldest)
        _HF_RIGHT_CACHE_SIZE[0] -= removed[2]
        _HF_RIGHT_CACHE_STATS['evictions'] += 1
    _HF_RIGHT_CACHE[key] = (_KrWeakRefs(_HF_RIGHT_CACHE_CONTEXT[0]['tag'][1]), encoded, size)
    _HF_RIGHT_CACHE_SIZE[0] += size
    _HF_RIGHT_CACHE_STATS['peak_bytes'] = max(_HF_RIGHT_CACHE_STATS['peak_bytes'], _HF_RIGHT_CACHE_SIZE[0])


import weakref as _kr_weakref


# Carried right encodings: a right operand that is a layer-invariant packing (a live _DF_PACK_CACHE value, the same
# object so the same values, or the shared zero-padded copy of one, see kr_pack_pad) and is presented again at a later
# layer with the same route is encoded once. The window (first, last) bounds the lifetime: entries are stored at layers
# first..last-1 and freed by their hit at layer last. Liveness: an entry neither stored nor hit during the previous layer
# is freed at the next layer start (its packing went to another route), so it is not held across a later layer's peak.
# A route listed in _KR_CARRY_LAST may end its window earlier. Rank-first NS encodings use the full window (L14 option): the
# L13 encoding is held into layer 14 to save its re-encode there, at about +336 MB across that layer's memory peak.
_KR_CARRY = {}
_KR_CARRY_LAYERS = (12, 14)
_KR_CARRY_LAST = {'ns_rank_first': 14}


# Zero-padded copies of live packings, keyed by (packing identity, pad widths): (weakref(packing), padded).
_KR_PADS = {}


def _kr_is_pack_value(value):
    for entries in _DF_PACK_CACHE.values():
        for entry in entries:
            # df_pack_put stores (refs, packed) pairs; skip anything else another cache may keep in this dict.
            if isinstance(entry, tuple) and len(entry) == 2 and entry[1] is value:
                return True
    return False


def _kr_is_carry_operand(value):
    """A live packing, or the shared padded copy (kr_pack_pad) of a live packing."""
    if _kr_is_pack_value(value):
        return True
    for (source, padded) in _KR_PADS.values():
        if padded is value:
            return _kr_is_pack_value(source())
    return False


def kr_pack_pad(value, widths):
    """fnp.pad(value, widths, mode='constant'), built once per live packing and widths: a later layer that pads the same
    packing (same object, so the same values) by the same widths gets the same padded array instead of a new copy."""
    key = (id(value), tuple((tuple(width) for width in widths)))
    found = _KR_PADS.get(key)
    if found is not None and found[0]() is value:
        return found[1]
    padded = fnp.pad(value, widths, mode='constant')
    if _kr_is_pack_value(value):
        _KR_PADS[key] = (_kr_weakref.ref(value), padded)
    return padded


def _kr_carry_last(route):
    return _KR_CARRY_LAST.get(route[0], _KR_CARRY_LAYERS[1])


def kr_carry_key(right, route):
    (first, last) = _KR_CARRY_LAYERS
    if _SI_D315_LAYER_CONTEXT > last:
        _KR_CARRY.clear()
    if not first <= _SI_D315_LAYER_CONTEXT <= _kr_carry_last(route) or not _kr_is_carry_operand(right):
        return None
    return (tuple(right.shape), str(right.dtype), route)


def kr_carry_purge():
    """At a layer start, free carried encodings whose right operand is no longer a live packing (it can never be presented
    again) or that were neither stored nor hit during the previous layer; free padded copies of dead packings."""
    layer = _SI_D315_LAYER_CONTEXT
    if layer > _KR_CARRY_LAYERS[1]:
        _KR_CARRY.clear()
    for key in [key for (key, found) in _KR_CARRY.items() if found[2] < layer - 1 or not _kr_is_carry_operand(found[0]())]:
        _KR_CARRY.pop(key)
    for key in [key for (key, found) in _KR_PADS.items() if not _kr_is_pack_value(found[0]())]:
        _KR_PADS.pop(key)


def kr_carry_get(key, right):
    if key is None:
        return None
    found = _KR_CARRY.get(key)
    if found is None or found[0]() is not right:
        return None
    if _SI_D315_LAYER_CONTEXT >= _kr_carry_last(key[2]):
        _KR_CARRY.pop(key)
    else:
        _KR_CARRY[key] = (found[0], found[1], _SI_D315_LAYER_CONTEXT)
    return found[1]


def kr_carry_put(key, right, encoded):
    if key is None or _SI_D315_LAYER_CONTEXT >= _kr_carry_last(key[2]):
        return
    _KR_CARRY[key] = (_kr_weakref.ref(right), encoded, _SI_D315_LAYER_CONTEXT)


class _KrWeakRefs:
    """The tagged operands of a history-cache entry, held weakly. Iterating yields each operand while it lives (None once
    freed), so hf_right_cache_get's identity test is unchanged, and an entry whose operands were freed can never hit again."""
    __slots__ = ('refs',)

    def __init__(self, items):
        refs = []
        for item in items:
            try:
                refs.append(_kr_weakref.ref(item))
            except TypeError:
                refs.append(_KrStrong(item))
        self.refs = tuple(refs)

    def __len__(self):
        return len(self.refs)

    def __iter__(self):
        return (ref() for ref in self.refs)

    def dead(self):
        for ref in self.refs:
            if type(ref) is _kr_weakref.ref and ref() is None:
                return True
        return False


class _KrStrong:
    """Strong holder with the weakref call interface, for a tag entry that cannot be weakly referenced."""
    __slots__ = ('item',)

    def __init__(self, item):
        self.item = item

    def __call__(self):
        return self.item


def hf_right_cache_purge():
    """Free the history-cache entries whose tagged operands no longer exist (hits need the same live objects)."""
    for key in [key for (key, found) in _HF_RIGHT_CACHE.items() if found[0].dead()]:
        _HF_RIGHT_CACHE_SIZE[0] -= _HF_RIGHT_CACHE.pop(key)[2]




_HF_RIGHT_CACHE_SEEN = {}


def _kz_top_padded_cost(m, k, n, kind, schemes, top, scaled):
    """Exact float32 charge of this existing top route, including movement."""
    depth = len(schemes)
    _tr_cf17_container_1 = []
    _tr_cf17_bound_2 = _tr_cf17_bound_3 = None
    try:
        for (_tr_cf17_bound_2, _tr_cf17_bound_3) in zip((m, k, n), kind):
            _tr_cf17_container_1.append(-(-_tr_cf17_bound_2 // (_tr_cf17_bound_3 << depth)) * (_tr_cf17_bound_3 << depth))
        (pm, pk, pn) = tuple(_tr_cf17_container_1)
    finally:
        del _tr_cf17_container_1, _tr_cf17_bound_2, _tr_cf17_bound_3
    cost = _kz_model((pm, pk, pn), top, schemes)
    cost += 2 * (pm * pk + pk * pn + pm * pn)
    if scaled:
        cost += pm * pk
    if (m, k) != (pm, pk):
        cost += pm * pk
    if (k, n) != (pk, pn):
        cost += pk * pn
    return cost


def _kz_output_peel_plan(m, k, n, kind, schemes):
    """Peel one short output edge only when its classical cost beats padding.

    The main rectangle keeps the already selected top, scheme sequence, and
    number of leaf products. The tail uses one ordinary matrix product.
    """
    key = (m, k, n, kind, schemes)
    if key in _KZ_OUTPUT_PEEL_PLANS:
        return _KZ_OUTPUT_PEEL_PLANS[key]
    (top, scaled) = _ops5_peel_top(kind)
    baseline = _kz_top_padded_cost(m, k, n, kind, schemes, top, scaled)
    best = None
    best_save = 0
    for axis in (0, 2):
        dims = (m, k, n)
        grid = kind[axis] << len(schemes)
        tail = dims[axis] % grid
        cut = dims[axis] - tail
        if tail == 0 or cut == 0:
            continue
        main = list(dims)
        main[axis] = cut
        cost = _kz_top_padded_cost(*main, kind, schemes, top, scaled)
        cost += tail * (n if axis == 0 else m) * (2 * k - 1)
        cost += m * n
        saving = baseline - cost
        if saving > best_save:
            best_save = saving
            best = (axis, cut)
    _KZ_OUTPUT_PEEL_PLANS[key] = best
    return best


def _kz_r40_padded_core(left, right, kind, schemes):
    """Owned padding to the selected top grid, product, then crop."""
    depth = len(schemes)
    ((m, k), n) = (left.shape, right.shape[1])
    _tr_cf17_container_1 = []
    _tr_cf17_bound_2 = _tr_cf17_bound_3 = None
    try:
        for (_tr_cf17_bound_2, _tr_cf17_bound_3) in zip((m, k, n), kind):
            _tr_cf17_container_1.append((_tr_cf17_bound_2 + (_tr_cf17_bound_3 << depth) - 1) // (_tr_cf17_bound_3 << depth) * (_tr_cf17_bound_3 << depth))
        (pm, pk, pn) = _tr_cf17_container_1
    finally:
        del _tr_cf17_container_1, _tr_cf17_bound_2, _tr_cf17_bound_3
    if pm != m or pk != k:
        left = fnp.pad(left, [(0, pm - m), (0, pk - k)], mode='constant')
    if pk != k or pn != n:
        right = fnp.pad(right, [(0, pk - k), (0, pn - n)], mode='constant')
    result = _kz_r40_matmul(left, right, kind, schemes)
    return result if (pm, pn) == (m, n) else result[:m, :n]


_KZ_OUTPUT_PEEL_PLANS = {}


def _kz_use_r48_root(left, right, schemes):
    """Replace two binary levels by rank 48 only for a large modeled saving.

    This decreases the leaf count from 49 to 48 per remaining subtree.
    The independent per-predict cap bounds the added graph/request work.
    """
    if _KZ_R48_TAKEN[0] >= int(KERNEL_CONFIG['hf_v9_r48_cap']) or len(schemes) != 6 or len(left.shape) != 2 or (len(right.shape) != 2):
        return False
    if str(left.dtype) != 'float32' or str(right.dtype) != 'float32':
        return False
    dims = (left.shape[0], left.shape[1], right.shape[1])
    if dims[2] < int(KERNEL_CONFIG['hf_v9_r48_aspect']) * max(dims[0], dims[1]):
        return False
    key = (dims, schemes)
    saving = _KZ_R48_SAVINGS.get(key)
    if saving is None:
        (m, k, n) = dims
        baseline = _kz_model(dims, None, schemes) + 3 * (m * k + k * n) // 4
        top = ((4, 4, 4), 48, (67, 67, 90), (0, 0, 0))
        candidate = _kz_model(dims, top, schemes[2:])
        saving = baseline - candidate
        _KZ_R48_SAVINGS[key] = saving
    if saving < int(KERNEL_CONFIG['hf_v9_r48_min_saving']):
        return False
    _KZ_R48_TAKEN[0] += 1
    return True


_KZ_R48_TAKEN = [0]


_KZ_R48_SAVINGS = {}


def far_row_scalar(data, rhs, weights):
    (far, moment_groups, raw_diagonal, row_keep, _far_ids) = data
    if row_keep is not None:
        rhs = rhs[row_keep, :]
    if isinstance(far, tuple):
        (first, last) = far
        _tr_cf17_container_1 = []
        _tr_cf17_bound_2 = _tr_cf17_bound_3 = None
        try:
            for (_tr_cf17_bound_2, _tr_cf17_bound_3) in ((0, first), (last, int(rhs.shape[0]))):
                if _tr_cf17_bound_3 > _tr_cf17_bound_2:
                    _tr_cf17_container_1.append((_tr_cf17_bound_2, _tr_cf17_bound_3))
            pieces = _tr_cf17_container_1
        finally:
            del _tr_cf17_container_1, _tr_cf17_bound_2, _tr_cf17_bound_3
    else:
        pieces = None
    total = None
    basis_rhs = {}
    for (first_block, second_block, repeated, suffix, squared, remainder_right, transported_left, factors) in moment_groups:
        width = int(suffix.shape[2])
        lazy_first = isinstance(first_block, tuple) and first_block[0] == 'sym_first'
        if lazy_first:
            _, twice_diagonal, six_free, first_values = first_block
        else:
            first_values = first_block
        live = int(first_values.shape[1])
        live_rhs = rhs if live >= int(rhs.shape[0]) else rhs[:live, :]
        if factors and all((factor[0] is None for factor in factors)):
            if live < int(repeated.shape[1]):
                (repeated, suffix) = (repeated[:, :live, :], suffix[:, :live, :])
            first_right = repeated.transpose(0, 2, 1) @ live_rhs
            second_right = suffix.transpose(0, 2, 1) @ live_rhs
        else:
            (first_parts, second_parts) = ([], [])
            (dense_first, dense_second) = lg_far_dense_readouts(repeated, suffix, factors, live_rhs)
            for (offset, (left, right, path, qoff)) in enumerate(factors):
                if left is None:
                    first_value = dense_first[offset]
                    second_value = dense_second[offset]
                else:
                    found = basis_rhs.get(id(left))
                    if found is None:
                        found = (left, left.T @ rhs)
                        basis_rhs[id(left)] = found
                    projected_rhs = found[1]
                    first_value = path @ projected_rhs
                    second_value = right @ projected_rhs
                    if qoff:
                        first_value = pad_axis(first_value, int(qoff), 0, 0)
                    first_value = pad_axis(first_value, 0, width - int(first_value.shape[0]), 0)
                    second_value = pad_axis(second_value, 0, width - int(second_value.shape[0]), 0)
                first_parts.append(first_value)
                second_parts.append(second_value)
            first_right = hf2_stack(first_parts, axis=0)
            second_right = hf2_stack(second_parts, axis=0)
        remainder_moments = transported_left.transpose(0, 2, 1) @ rhs
        if pieces is None:
            domains = [(first_values[:, far, :], second_block[:, far, :], squared[:, far, :], weights[None, None, :])]
        else:
            domains = []
            offset = 0
            for (low, high) in pieces:
                stop = min(high, int(first_values.shape[1]))
                if stop > low:
                    # The (1, 1, m) weight view in one getitem (was a slice, then [None, None, :]): the same view, one request less.
                    domains.append((first_values[:, low:stop, :], second_block[:, low:stop, :], squared[:, low:stop, :], weights[None, None, offset:offset + stop - low]))
                offset += high - low
        for (first_piece, second_piece, squared_piece, weighted) in domains:
            weighted_squared = weighted @ squared_piece
            if lazy_first:
                first_left = twice_diagonal * (weighted @ first_piece) + six_free * weighted_squared
            else:
                first_left = weighted @ first_piece
            second_left = weighted @ second_piece
            remainder_left = weighted_squared @ remainder_right
            value = first_left @ first_right + second_left @ second_right + remainder_left @ remainder_moments
            scalar = ONE_THIRD * fnp.sum(value)
            total = scalar if total is None else total + scalar
    if pieces is None:
        far_rhs = rhs[far, 0]
    else:
        far_rhs = rhs[pieces[0][0]:pieces[0][1], 0] if len(pieces) == 1 else fnp.concatenate([rhs[low:high, 0] for (low, high) in pieces], axis=0)
    return total - fnp.sum(weights * raw_diagonal * far_rhs)


def _sym_source_domains(state, original, combined, width):
    """Minimize genuine live support at no more existing support waves.

    The bounds are source construction metadata, not observed numerical zeros.
    Only a plan strictly smaller than the current one is admitted.
    """
    plans = state.runtime.readout.setdefault('sym_source_domain_plans', {})
    key = (tuple(original), tuple(combined), width)
    found = plans.get(key)
    if found is False:
        return combined
    if found is not None:
        return found
    old_area = sum([hi - lo for (lo, hi) in combined])
    if 16 * (len(combined) * width - old_area) < len(combined) * width:
        plans[key] = False
        return combined
    if old_area == sum([hi - lo for (lo, hi) in original]):
        plans[key] = False
        return combined
    answer = list(combined)
    first = 0
    while first < len(original):
        if original[first][1] <= original[first][0]:
            first += 1
            continue
        stop = first + 1
        while stop < len(original) and original[stop][1] > original[stop][0]:
            stop += 1
        waves = 1 + sum([combined[i] != combined[i - 1] for i in range(first + 1, stop)])
        n = stop - first
        if waves > 1:
            bands = {}
            for lo in range(n):
                (low, high) = original[first + lo]
                for hi in range(lo + 1, n + 1):
                    low = min(low, original[first + hi - 1][0])
                    high = max(high, original[first + hi - 1][1])
                    bands[lo, hi] = (low, high, (hi - lo) * (high - low))
            dp = {(0, 0): (0, ())}
            for groups in range(1, waves + 1):
                for hi in range(groups, n + 1):
                    best = None
                    for lo in range(groups - 1, hi):
                        previous = dp.get((groups - 1, lo))
                        if previous is None:
                            continue
                        (low, high, area) = bands[lo, hi]
                        proposal = (previous[0] + area, previous[1] + ((lo, hi, low, high),))
                        if best is None or proposal[0] < best[0]:
                            best = proposal
                    if best is not None:
                        dp[groups, hi] = best
            best = min([v for ((g, hi), v) in dp.items() if hi == n], key=lambda v: (v[0], len(v[1])))
            if best[0] < sum([hi - lo for (lo, hi) in combined[first:stop]]):
                for (lo, hi, low, high) in best[1]:
                    answer[first + lo:first + hi] = [(low, high)] * (hi - lo)
        first = stop
    answer = tuple(answer)
    plans[key] = answer
    return answer


# whest3 paid knob (request seller), v103 port: None keeps v103's thresholds (16 in the source plans, sym2_parent_hf2_support_threshold
# in the early parent path); 0 always takes the full-product fast path.
_W3K_HF2_SUPPORT_THRESHOLD = PARAMS['_W3K_HF2_SUPPORT_THRESHOLD']


def _sym_uncached_source_plan(state, indices, left, q_prefix=False, zero_first=False):
    width = int(left.shape[2])
    domains = []
    for index in indices:
        low = int(state.q_offsets[index]) if q_prefix else 0
        high = min(width, int(state.source_free_u[index].shape[0]))
        if zero_first and index == 0:
            low = high = 0
        domains.append((low, high))
    combined = list(domains)
    begin = 0
    while begin < len(domains):
        if domains[begin][1] <= domains[begin][0]:
            begin += 1
            continue
        stop = begin + 1
        while stop < len(domains) and domains[stop][1] > domains[stop][0]:
            stop += 1
        groups = int(PARAMS['hf2_support_groups'])
        size = max(1, (stop - begin + groups - 1) // groups)
        for first in range(begin, stop, size):
            last = min(stop, first + size)
            low = min([value[0] for value in domains[first:last]])
            high = max([value[1] for value in domains[first:last]])
            combined[first:last] = [(low, high)] * (last - first)
        begin = stop
    domains = _sym_source_domains(state, domains, combined, width)
    omitted_columns = sum([width - high + low for (low, high) in domains])
    if (16 if _W3K_HF2_SUPPORT_THRESHOLD is None else _W3K_HF2_SUPPORT_THRESHOLD) * omitted_columns < len(indices) * width:
        return (False, tuple(domains))
    if all([low == 0 and high == width for (low, high) in domains]):
        return (False, tuple(domains))
    return (True, tuple(domains))


def _sym_source_plan(state, indices, left, q_prefix=False, zero_first=False):
    # readout is cleared by prepare_layer. These source widths and q offsets
    # are immutable throughout this layer's polynomial consumers.
    plans = state.runtime.readout.setdefault('sym_source_cached_plans', {})
    key = (tuple(indices), int(left.shape[2]), q_prefix, zero_first)
    found = plans.get(key)
    if found is None:
        partial, domains = _sym_uncached_source_plan(state, indices, left, q_prefix, zero_first)
        waves = []
        first = 0
        while first < len(indices):
            low, high = domains[first]
            last = first + 1
            while last < len(indices) and domains[last] == domains[first]:
                last += 1
            if high > low:
                waves.append((first, last, low, high))
            first = last
        found = (partial, domains, tuple(waves))
        plans[key] = found
    return found

def _sym_source_operand_piece(views, value, begin, end, column_begin, column_end):
    key = (id(value), begin, end, column_begin, column_end)
    found = views.get(key)
    if found is None or found[0] is not value:
        full_batch = begin in (None, 0) and end in (None, int(value.shape[0]))
        full_columns = column_begin in (None, 0) and column_end in (None, int(value.shape[2]))
        part = value if full_batch and full_columns else value[slice(begin, end), :, slice(column_begin, column_end)]
        found = (value, part)
        _cmp_store_view(views, key, found)
    return found[1]


def hf2_source_product(state, indices, left, right, q_prefix=False, zero_first=False, out=None, plan=None):
    if plan is None:
        plan = _sym_source_plan(state, indices, left, q_prefix, zero_first)
    partial, domains, waves = plan
    if not partial:
        return left * right if out is None else fnp.multiply(left, right, out=out)
    if str(left.dtype) != str(right.dtype):
        return left * right if out is None else fnp.multiply(left, right, out=out)
    if zero_first and all([high <= low for (low, high) in domains]):
        return None
    result = out
    if result is None:
        result = fnp.zeros(left.shape, dtype=left.dtype)
        if len(set(left.shape)) < len(left.shape):
            result = fnp.asarray(result)
    views = state.runtime.readout.setdefault('hf2_product_views', {})
    # BUNDLE selectors use the existing SYM2 plan and flat view-cache keys.
    _cmp_right_kind = (1 if int(right.shape[0]) == 1 else 0) + (2 if int(right.shape[2]) == 1 else 0)
    _cmp_piece, _cmp_multiply = _sym_source_operand_piece, fnp.multiply
    for first, last, low, high, left_key, _, right_keys, _ in _cmp_product_selectors(tuple(waves)):
        left_piece = _cmp_piece(views, left, *left_key)
        right_piece = left_piece if right is left else _cmp_piece(views, right, *right_keys[_cmp_right_kind])
        target = _cmp_piece(views, result, *left_key)
        _cmp_multiply(left_piece, right_piece, out=target)
    return result


def hf2_stack(parts, axis=0, **kwargs):
    if axis == 0 and (not kwargs) and isinstance(parts, (list, tuple)) and (len(parts) == 1):
        first = parts[0]
        if hasattr(first, 'shape') and hasattr(first, 'dtype'):
            return first[None, ...]
    return fnp.stack(parts, axis=axis, **kwargs)


def hf2_source_scale(state, coefficient, vector):
    key = ('hf2_source_scale', id(coefficient), id(vector))
    found = state.source_padding.get(key)
    if found is None or found[0] is not coefficient or found[1] is not vector:
        found = (coefficient, vector, (coefficient * vector)[:, None, :])
        state.source_padding[key] = found
    return found[2]


def hf2_q_front_stack(runtime, parts, offsets, width):
    _ops5_pub_unstack = fnp.unstack
    dtype = parts[0].dtype
    if any((part.dtype != dtype for part in parts)):
        return elementwise_stack([diagonal_q_front(runtime, part, qoff, width) for (part, qoff) in zip(parts, offsets)], width, -1)
    keys = tuple(((int(offset), int(part.shape[1])) for (part, offset) in zip(parts, offsets)))
    (full, all_mode, shifted, runs, positive) = _ops3_q_stack_plan(keys, int(width))
    if full:
        return hf2_stack(parts, axis=0)
    rows = int(parts[0].shape[0])
    result = fnp.zeros((len(parts) if all_mode else len(shifted), rows, width), dtype=dtype)
    for (first, last, target) in runs:
        if last - first == 1:
            part = parts[first] if all_mode else parts[shifted[first]]
            fnp.copyto(result[target], part)
        else:
            leaves = list(parts[first:last]) if all_mode else [parts[i] for i in shifted[first:last]]
            hf2_stack(leaves, axis=0, out=result[target])
    if all_mode:
        views = _ops5_pub_unstack(result, axis=0) if positive else ()
    else:
        leaves = list(parts)
        for (index, leaf) in zip(shifted, _ops5_pub_unstack(result, axis=0)):
            leaves[index] = leaf
        result = fnp.stack(leaves, axis=0)
        views = _ops5_pub_unstack(result, axis=0)
    if positive:
        front = runtime.readout.setdefault('wide_q_front', {})
        for i in positive:
            part = parts[i]
            front[id(part)] = (part, offsets[i], width, views[i])
    return result


