def _ns_padded(left, right, spec):
    (kind, rank, funcs, schemes, scale) = spec
    levels = len(schemes)
    (m, k, n) = (left.shape[-2], left.shape[-1], right.shape[-1])
    _tr_cf17_container_1 = []
    _tr_cf17_bound_2 = _tr_cf17_bound_3 = None
    try:
        for (_tr_cf17_bound_2, _tr_cf17_bound_3) in zip((m, k, n), kind):
            _tr_cf17_container_1.append(-(-_tr_cf17_bound_2 // (_tr_cf17_bound_3 << levels)) * (_tr_cf17_bound_3 << levels))
        (pm, pk, pn) = tuple(_tr_cf17_container_1)
    finally:
        del _tr_cf17_container_1, _tr_cf17_bound_2, _tr_cf17_bound_3
    if scale != 1.0:
        left = fnp.multiply(left, scale)
    if pm != m or pk != k:
        left = fnp.pad(left, [(0, 0)] * (len(left.shape) - 2) + [(0, pm - m), (0, pk - k)], mode='constant')
    if pk != k or pn != n:
        right = fnp.pad(right, [(0, 0)] * (len(right.shape) - 2) + [(0, pk - k), (0, pn - n)], mode='constant')
    result = _ns_top(left, right, kind, rank, funcs, schemes)
    return result if pm == m and pn == n else result[..., :m, :n]


