def _tr_factor_execute(graph, inputs, xp):
    values = {-i - 1: x for (i, x) in enumerate(inputs)}
    for (op, rows) in graph['groups']:
        fn = xp.add if op == 'add' else xp.subtract
        if len(rows) == 1:
            # one-row group: the same element-wise op on the operands themselves (no batch, no unstack)
            values[rows[0][0]] = fn(values[rows[0][1]], values[rows[0][2]])
            continue
        batch = fn(tuple([values[a] for (_, a, b) in rows]), tuple([values[b] for (_, a, b) in rows]))
        for ((i, a, b), value) in zip(rows, xp.unstack(batch, axis=0)):
            values[i] = value
    _tr_cf17_container_1 = []
    _tr_cf17_bound_2 = None
    try:
        for _tr_cf17_bound_2 in graph['outputs']:
            _tr_cf17_container_1.append(None if _tr_cf17_bound_2 is None else values[_tr_cf17_bound_2])
        return _tr_cf17_container_1
    finally:
        del _tr_cf17_container_1, _tr_cf17_bound_2

def _tr_factor_product(A, B):
    if min(A.shape[-2], A.shape[-1], B.shape[-1]) < 64:
        return A @ B
    (m, k, n) = (A.shape[-2], A.shape[-1], B.shape[-1])
    d = 4
    step = 1 << d
    _tr_cf17_container_1 = []
    _tr_cf17_bound_2 = None
    try:
        for _tr_cf17_bound_2 in (m, k, n):
            _tr_cf17_container_1.append((_tr_cf17_bound_2 + step - 1) // step * step)
        (pm, pk, pn) = _tr_cf17_container_1
    finally:
        del _tr_cf17_container_1, _tr_cf17_bound_2
    if pm != m:
        A = pad_axis(A, 0, pm - m, len(A.shape) - 2)
    if pk != k:
        A = pad_axis(A, 0, pk - k, len(A.shape) - 1)
        B = pad_axis(B, 0, pk - k, len(B.shape) - 2)
    if pn != n:
        B = pad_axis(B, 0, pn - n, len(B.shape) - 1)
    ans = _kz_matmul(A, B, _kz_schemes(d, pm * pk * pn, 0))
    return ans if (pm, pn) == (m, n) else ans[..., :m, :n]

def _tr_factor_tri_leaf(A, B):
    width = int(A.shape[-1])
    columns = int(B.shape[-1])
    groups = {}
    leaves = []

    def visit(lo, hi):
        size = hi - lo
        if size <= 8:
            leaves.append((lo, hi))
            return
        mid = lo + max(8, size // 16 * 8)
        groups.setdefault((mid - lo, hi - mid), []).append((lo, mid, hi))
        visit(lo, mid)
        visit(mid, hi)
    visit(0, width)
    out = fnp.asarray(fnp.zeros(A.shape[:-2] + (width, columns), dtype=A.dtype))
    for (dims, regions) in groups.items():
        L = hf2_stack([A[..., lo:mid, mid:hi] for (lo, mid, hi) in regions])
        R = hf2_stack([B[..., mid:hi, :] for (lo, mid, hi) in regions])
        for (value, (lo, mid, hi)) in zip(fnp.unstack(_tr_factor_product(L, R)), regions):
            view = out[..., lo:mid, :]
            fnp.add(view, value, out=view)
    for (lo, hi) in leaves:
        value = A[..., lo:hi, lo:hi] @ B[..., lo:hi, :]
        view = out[..., lo:hi, :]
        fnp.add(view, value, out=view)
    return out

def _tr_factor_triangular(A, B, levels):
    _ops5_pub_split = fnp.split
    size = int(A.shape[-1])
    if levels == 0 or size % 4 or int(B.shape[-1]) % 4 or (size < 32):
        return _tr_factor_tri_leaf(A, B)
    rows = _ops5_pub_split(A, 4, axis=-2)
    _tr_cf17_container_1 = []
    _tr_cf17_bound_2 = _tr_cf17_bound_3 = _tr_cf17_bound_4 = _tr_cf17_bound_5 = None
    try:
        for (_tr_cf17_bound_2, _tr_cf17_bound_3) in enumerate(rows):
            for (_tr_cf17_bound_4, _tr_cf17_bound_5) in enumerate(_ops5_pub_split(_tr_cf17_bound_3, 4, axis=-1)):
                if _tr_cf17_bound_2 <= _tr_cf17_bound_4:
                    _tr_cf17_container_1.append(_tr_cf17_bound_5)
        left = _tr_cf17_container_1
    finally:
        del _tr_cf17_container_1, _tr_cf17_bound_2, _tr_cf17_bound_3, _tr_cf17_bound_4, _tr_cf17_bound_5
    _tr_cf17_container_6 = []
    _tr_cf17_bound_7 = _tr_cf17_bound_8 = None
    try:
        for _tr_cf17_bound_7 in _ops5_pub_split(B, 4, axis=-2):
            for _tr_cf17_bound_8 in _ops5_pub_split(_tr_cf17_bound_7, 4, axis=-1):
                _tr_cf17_container_6.append(_tr_cf17_bound_8)
        right = _tr_cf17_container_6
    finally:
        del _tr_cf17_container_6, _tr_cf17_bound_7, _tr_cf17_bound_8
    L = hf2_stack(_tr_factor_execute(_TR_FACTOR_UG[0], left, fnp))
    R = hf2_stack(_tr_factor_execute(_TR_FACTOR_UG[1], right, fnp))
    rec = _tr_factor_triangular(L[:12], R[:12], levels - 1)
    gen = _tr_factor_product(L[12:], R[12:])
    outputs = _tr_factor_execute(_TR_FACTOR_UG[2], tuple(fnp.unstack(rec)) + tuple(fnp.unstack(gen)), fnp)
    return fnp.block([outputs[i * 4:(i + 1) * 4] for i in range(4)])

def _tr_factor_gram(A, levels):
    _ops5_pub_unstack = fnp.unstack
    (m, k) = (int(A.shape[-2]), int(A.shape[-1]))
    if levels == 0 or m % 4 or k % 4 or (m < 32):
        prefix = 'abcdefgh'[:len(A.shape) - 2]
        subscripts = prefix + 'ik,' + prefix + 'jk->' + prefix + 'ij'
        return fnp.einsum(subscripts, A, A, symmetry=(len(A.shape) - 2, len(A.shape) - 1))
    _tr_cf17_container_1 = []
    _tr_cf17_bound_2 = _tr_cf17_bound_3 = None
    try:
        for _tr_cf17_bound_2 in fnp.split(A, 4, axis=-2):
            for _tr_cf17_bound_3 in fnp.split(_tr_cf17_bound_2, 4, axis=-1):
                _tr_cf17_container_1.append(_tr_cf17_bound_3)
        parts = _tr_cf17_container_1
    finally:
        del _tr_cf17_container_1, _tr_cf17_bound_2, _tr_cf17_bound_3
    L = hf2_stack(_tr_factor_execute(_TR_FACTOR_GT[0], parts, fnp))
    R = hf2_stack([p.transpose(*range(len(p.shape) - 2), len(p.shape) - 1, len(p.shape) - 2) for p in _tr_factor_execute(_TR_FACTOR_GT[1], parts, fnp)])
    rec = _tr_factor_gram(L[:2], levels - 1)
    gen = _tr_factor_product(L[2:], R)
    outputs = _tr_factor_execute(_TR_FACTOR_GT[2], tuple(_ops5_pub_unstack(rec)) + tuple(_ops5_pub_unstack(gen)), fnp)
    blocks = dict(zip([(i, j) for i in range(4) for j in range(i, 4)], outputs))
    corner_rows = int(A.shape[-2]) // 4
    corner_inputs = hf2_stack([A[..., :corner_rows, :], A[..., 3 * corner_rows:, :]])
    corner_outputs = _tr_factor_gram(corner_inputs, levels - 1)
    (blocks[0, 0], blocks[3, 3]) = _ops5_pub_unstack(corner_outputs, axis=0)
    return fnp.block([[blocks[i, j] if i <= j else fnp.swapaxes(blocks[j, i], -2, -1) for j in range(4)] for i in range(4)])

def hierarchical_covariance(cov, weight, transported=None):
    if int(weight.shape[1]) != 1024 or transported is not None or int(weight.shape[0]) > 1024 or int(weight.shape[0]) > 864:
        return _tr_factor_parent(cov, weight, transported)
    _tr_original_covariance = cov
    cov = cov.T
    diagonal = fnp.diag(cov)
    order = fnp.argsort(diagonal, stable=True)
    inverse = fnp.argsort(order, stable=True)
    count = min(16, int(weight.shape[0]))
    delta = fnp.max(fnp.abs(diagonal)) * 1e-05
    changed = diagonal[order]
    changed_head = changed[:count]
    fnp.add(changed_head, delta, out=changed_head)
    shifted = fnp.copy(cov, order='C')
    fnp.fill_diagonal(shifted, changed[inverse])
    try:
        lower = fnp.linalg.cholesky(shifted)
    except Exception as error:
        if 'positive definite' not in str(error).replace('-', ' '):
            raise
        return _tr_factor_parent(_tr_original_covariance, weight)
    transformed = _tr_factor_triangular(lower.T, weight, 3)
    positive = _tr_factor_gram(transformed.T, 1)
    selected = weight[order[:count], :]
    correction = fnp.einsum('ia,ib->ab', selected, selected, symmetry=(0, 1))
    return positive - delta * correction


# NS transient layer context; restored before every layer-step return.
_SI_D315_LAYER_CONTEXT = -1


_DF_PACK_CACHE = {}


def df_pack_get(role, parts):
    """Reuse a packing of layer-invariant leg factors (same objects, so the same values) built at an earlier layer."""
    for (refs, value) in _DF_PACK_CACHE.get(role, ()):
        if len(refs) == len(parts) and _tr_same_object_references(refs, parts):
            return value
    return None


def df_pack_put(role, parts, value):
    entries = _DF_PACK_CACHE.setdefault(role, [])
    entries.append((tuple(parts), value))
    del entries[:-int(PARAMS['pr1_pack_cache_slots'])]


def drop_column(x, drop, pad=False):
    """x[:, every column but drop] (optionally plus one trailing zero column) from slices, not a paid gather."""
    pieces = []
    if drop > 0:
        pieces.append(x[:, :drop])
    if drop + 1 < int(x.shape[1]):
        pieces.append(x[:, drop + 1:])
    if pad:
        pieces.append(fnp.zeros((int(x.shape[0]), 1), dtype=x.dtype))
    columns = sum([int(piece.shape[1]) for piece in pieces])
    # Same column-major layout as numpy's x[:, ids] gather (and np.pad keeps it), so later BLAS calls are unchanged.
    return fnp.concatenate(pieces, axis=1, out=fnp.zeros((columns, int(x.shape[0])), dtype=x.dtype).T)

def _tr_same_object_references(left, right):
    for (a, b) in zip(left, right):
        if a is not b:
            return False
    return True


# Frozen KE deep/generic route family; caller science and assets stay in the parent.
_KX_DONOR_PARENT_FAST = _fast_matmul
_kx_donor_fast_matmul = _fast_matmul
def _kx_donor_ns_c0_0(inputs):
    """Exact DAG with a bounded owned temporary pool; no runtime caches."""
    _ops5_pub_subtract = fnp.subtract
    i0 = inputs[0]
    i1 = inputs[1]
    i2 = inputs[2]
    i3 = inputs[3]
    i4 = inputs[4]
    i5 = inputs[5]
    i6 = inputs[6]
    i7 = inputs[7]
    pool = fnp.empty((18,) + inputs[0].shape, dtype=inputs[0].dtype)
    q = fnp.unstack(pool, axis=0)
    _v_pool = fnp.split(pool, (1, 6, 6, 9, 9, 14, 14, 18), axis=0)
