'New exact top runtime; only public metered operations.'

def _kx_donor_ns_top(left, right, kind, rank, funcs, schemes):
    _ops5_pub_unstack = fnp.unstack
    (rm, rk, rn) = kind
    levels = len(schemes)
    m = left.shape[-2] // (rm << levels)
    k = left.shape[-1] // (rk << levels)
    n = right.shape[-1] // (rn << levels)
    (left_prefix, right_prefix) = (left.shape[:-2], right.shape[:-2])
    (lp, rp) = (len(left_prefix), len(right_prefix))
    blocked_left = _kz_blocked_top(left, schemes, False, rm, rk)
    blocked_right = _kz_blocked_top(right, schemes, True, rk, rn)
    _kz_basis(blocked_left, lp, schemes, 0, False)
    _kz_basis(blocked_right, rp, schemes, 0, True)
    encoded_left = fnp.empty(left_prefix + (7,) * levels + (rank, m, k), dtype=left.dtype)
    encoded_right = fnp.empty(right_prefix + (7,) * levels + (rank, k, n), dtype=right.dtype)
    lr = _kz_regions(schemes, _KZ_LEFT, -1)
    rr = _kz_regions(schemes, _KZ_RIGHT, -1)
    left_target = encoded_left[(slice(None),) * lp + lr] if levels else encoded_left
    left_axes = (lp + levels,) + tuple((i for i in range(len(left_target.shape)) if i != lp + levels))
    fnp.copyto(fnp.transpose(left_target, left_axes), funcs[0](_ops5_pub_unstack(blocked_left, axis=lp + levels)))
    funcs[1](_ops5_pub_unstack(blocked_right, axis=rp + levels), encoded_right[(slice(None),) * rp + rr] if levels else encoded_right, rp + levels)
    del left_target
    del blocked_left, blocked_right
    _kz_encode_levels(encoded_left, lp, schemes, 0, False)
    _kz_encode_levels(encoded_right, rp, schemes, 0, True)
    products = fnp.matmul(encoded_left, encoded_right)
    del encoded_left, encoded_right
    base = len(products.shape) - levels - 3
    _kz_decode(products, base, schemes)
    out_regions = _kz_regions(schemes, _KZ_OUT, -1)
    result = fnp.stack(funcs[2](_ops5_pub_unstack(products[(slice(None),) * base + out_regions] if levels else products, axis=base + levels)), axis=base + levels)
    del products
    _kz_output(result, base, schemes, 0)
    return _kz_unblocked_top(result, levels, rm, rn)

def _kx_donor_ns_padded(left, right, spec):
    (kind, rank, funcs, schemes, scale) = spec
    levels = len(schemes)
    (m, k, n) = (left.shape[-2], left.shape[-1], right.shape[-1])
    (pm, pk, pn) = tuple((-(-v // (q << levels)) * (q << levels) for (v, q) in zip((m, k, n), kind)))
    if scale != 1.0:
        left = fnp.multiply(left, scale)
    if pm != m or pk != k:
        left = fnp.pad(left, [(0, 0)] * (len(left.shape) - 2) + [(0, pm - m), (0, pk - k)], mode='constant')
    if pk != k or pn != n:
        right = fnp.pad(right, [(0, 0)] * (len(right.shape) - 2) + [(0, pk - k), (0, pn - n)], mode='constant')
    result = _kx_donor_ns_top(left, right, kind, rank, funcs, schemes)
    return result if pm == m and pn == n else result[..., :m, :n]

_kx_donor_NS_PARENT_FAST_MATMUL = _kx_donor_fast_matmul

def _kx_donor_fast_matmul(*_kx2_call_args, **_kx2_call_kwargs):
    if len(_kx2_call_args) < 2 or len(_kx2_call_args) > 4 or (not _kx2_call_kwargs.keys() <= _OPS5_WRAPPER_KEYS) or (len(_kx2_call_args) > 2 and 'leg_transport' in _kx2_call_kwargs) or (len(_kx2_call_args) > 3 and 'hf_right_tag' in _kx2_call_kwargs):
        return _KX_DONOR_PARENT_FAST(*_kx2_call_args, **_kx2_call_kwargs)
    (left, right) = _kx2_call_args[:2]
    leg_transport = _kx2_call_kwargs.get('leg_transport', _kx2_call_args[2] if len(_kx2_call_args) > 2 else False)
    hf_right_tag = _kx2_call_kwargs.get('hf_right_tag', _kx2_call_args[3] if len(_kx2_call_args) > 3 else None)
    if str(left.dtype) == 'float32' and str(right.dtype) == 'float32':
        key = (left.shape, right.shape, bool(leg_transport))
        spec = _kx_donor_NS_ROUTES.get(key)
        if spec is not None:
            if len(left.shape) == 2 and len(right.shape) == 2:
                before = tuple(_KZ_R40_TAKEN)
                parent_top = _kz_r40_route(int(left.shape[0]), int(left.shape[1]), int(right.shape[1]))
                if parent_top is not None and key in _kx_donor_NS_NO_R40:
                    _KZ_R40_TAKEN[:] = before
                    return _kx_donor_NS_PARENT_FAST_MATMUL(*_kx2_call_args, **_kx2_call_kwargs)
                if parent_top is None:
                    descriptor = _kx_donor_NS_PARENT_KZ.get(key)
                    if descriptor is not None:
                        (ls, rs, parent_schemes) = descriptor
                        _kz_use_r48_root(SimpleNamespace(shape=ls, dtype=left.dtype), SimpleNamespace(shape=rs, dtype=right.dtype), parent_schemes)
            return _kx_donor_ns_padded(left, right, spec)
    return _kx_donor_NS_PARENT_FAST_MATMUL(*_kx2_call_args, **_kx2_call_kwargs)

