_KX_AVOID_SHAPES = frozenset(_NS_ROUTES) | frozenset(_SI115_NS_ROUTES) | frozenset(_kx_donor_NS_ROUTES) | frozenset(_kx_donor_ke_ng__NS_ROUTES)

# Shape-only route metadata; coefficients are real-client counted FLOPs, not learned values.
_KX_GENERIC_PARENT_FAST = _fast_matmul

def _kx_route_price(m, k, n, model):
    kind, schemes, coefficients, requests, funcs, scale = model
    if kind == (2, 2, 2):
        grids = (1 << len(schemes),) * 3
    else:
        grids = tuple(v << len(schemes) for v in kind)
    pm, pk, pn = tuple(-(-v // g) * g for v, g in zip((m, k, n), grids))
    mm, kk, nn = tuple(v // g for v, g in zip((pm, pk, pn), grids))
    a, b, c, products = coefficients
    cost = a * mm * kk + b * kk * nn + c * mm * nn + products * mm * nn * (2 * kk - 1)
    if pm != m or pk != k:
        cost += pm * pk
        requests += 1
    if pk != k or pn != n:
        cost += pk * pn
        requests += 1
    if pm != m or pn != n:
        requests += 1
    if scale != 1.0:
        cost += m * k
        requests += 1
    elements = products * (mm * kk + kk * nn + mm * nn)
    return cost, requests, elements, products * mm * nn

def _kx_parent_depth(m, k, n):
    leaf = int(KERNEL_CONFIG['ck_leaf_size'])
    depth = min(int(KERNEL_CONFIG['ck_max_depth']), max(0, (min(m, k, n) // leaf).bit_length() - 1))
    shallow = int(KERNEL_CONFIG.get('kw_shallow_volume', 0))
    if shallow > 0 and depth >= 6 and m * k * n <= shallow:
        depth = 5
    tiny_short = int(KERNEL_CONFIG.get('kw_tiny_leaf_short', 0))
    tiny_long = int(KERNEL_CONFIG.get('kw_tiny_leaf_long', 0))
    tiny_work = int(KERNEL_CONFIG.get('kz_tiny_work', 0))
    divisor = 1 << depth
    padded = tuple(-(-v // divisor) * divisor for v in (m, k, n))
    exempt = tiny_work > 0 and m * k * n >= tiny_work and depth >= int(KERNEL_CONFIG.get('kv_packed_depth_min', 0)) and (padded == (m, k, n) or (int(KERNEL_CONFIG.get('kz_tiny_pad', 0)) > 0 and math.prod(padded) * 10000 <= m * k * n * int(KERNEL_CONFIG['ck_pad_limit'])))
    if tiny_short > 0 and tiny_long > 0 and not exempt:
        while depth > 0:
            dimensions = sorted(-(-v // (1 << depth)) for v in (m, k, n))
            if dimensions[1] > tiny_short or dimensions[2] > tiny_long:
                break
            depth -= 1
    limit = int(KERNEL_CONFIG.get('kw_leaf_product_limit', 0))
    if limit > 0:
        while depth > 0 and 7 ** depth > limit:
            depth -= 1
    deep = int(KERNEL_CONFIG.get('kz_deep_work', 0))
    if deep > 0 and depth == int(KERNEL_CONFIG['ck_max_depth']) and m * k * n >= deep and not any(v % (2 << depth) for v in (m, k, n)) and min(m, k, n) >= (leaf - 1) << (depth + 1):
        depth += 1
    multiple = int(KERNEL_CONFIG['ck_pad_multiple'])
    policy = int(KERNEL_CONFIG.get('kw_padding_policy', 0))
    if multiple > 0 and depth > 0 and policy > 0:
        multiple = min(multiple, 1 << depth) if policy == 1 else 1 << depth
    return depth, multiple


def _kx_reference_model(m, k, n, kind, schemes):
    key = (kind, schemes)
    if kind in _KZ_R20_GRAPHS and kind not in _KP_R40_GRAPHS:
        grids = tuple(v << len(schemes) for v in kind)
        leaves = tuple(-(-v // g) for v, g in zip((m, k, n), grids))
        mm, kk, nn = leaves
        rank = len(_KZ_R20_GRAPHS[kind][0][1])
        packed_bytes = 4 * rank * 7 ** len(schemes) * (mm * kk + kk * nn + mm * nn)
        if packed_bytes >= int(PARAMS['rf_r20_stream_threshold_bytes']):
            key = (kind, schemes, 'stream')
    return _KX_REFERENCE_MODELS.get(key)

def _kx_reference_route(m, k, n):
    before = tuple(_KZ_R40_TAKEN)
    direct = _kz_r40_route(m, k, n)
    _KZ_R40_TAKEN[:] = before
    if direct is not None:
        kind, depth = direct
    else:
        depth, multiple = _kx_parent_depth(m, k, n)
        selected = _kz_r20_route(m, k, n, depth, multiple) if depth >= 4 else None
        if selected is not None:
            kind, depth = selected
        else:
            kind = (2, 2, 2)
    if kind == (2, 2, 2):
        grids = (1 << depth,) * 3
        top = 1
    else:
        grids = tuple(v << depth for v in kind)
        top = 0
    padded = tuple(-(-v // g) * g for v, g in zip((m, k, n), grids))
    schemes = _kz_schemes(depth, math.prod(padded), top)
    model = _kx_reference_model(m, k, n, kind, schemes)
    if model is None:
        return None
    cost, requests, elements, output = _kx_route_price(m, k, n, model)
    if kind != (2, 2, 2):
        peel = _kz_output_peel_plan(m, k, n, kind, schemes)
        if peel is not None:
            axis, cut = peel
            dims = [m, k, n]
            tail = dims[axis] - cut
            dims[axis] = cut
            model = _kx_reference_model(*dims, kind, schemes)
            if model is None:
                return None
            cost, requests, elements, output = _kx_route_price(*dims, model)
            cost += tail * (n if axis == 0 else m) * (2 * k - 1) + m * n
            requests += 4
    return cost, requests, direct, kind, schemes

def _fast_matmul(*_kx2_call_args, **_kx2_call_kwargs):
    if len(_kx2_call_args) < 2 or len(_kx2_call_args) > 4 or (not _kx2_call_kwargs.keys() <= _OPS5_WRAPPER_KEYS) or (len(_kx2_call_args) > 2 and 'leg_transport' in _kx2_call_kwargs) or (len(_kx2_call_args) > 3 and 'hf_right_tag' in _kx2_call_kwargs):
        return _KX_DONOR_PARENT_FAST(*_kx2_call_args, **_kx2_call_kwargs)
    (left, right) = _kx2_call_args[:2]
    leg_transport = _kx2_call_kwargs.get('leg_transport', _kx2_call_args[2] if len(_kx2_call_args) > 2 else False)
    hf_right_tag = _kx2_call_kwargs.get('hf_right_tag', _kx2_call_args[3] if len(_kx2_call_args) > 3 else None)
    if len(left.shape) != 2 or len(right.shape) != 2 or str(left.dtype) != 'float32' or (str(right.dtype) != 'float32') or leg_transport:
        return _KX_GENERIC_PARENT_FAST(*_kx2_call_args, **_kx2_call_kwargs)
    (m, k, n) = (left.shape[0], left.shape[1], right.shape[1])
    thin_wide = 512 <= m <= 1024 and 128 <= k <= 384 and (n >= 4096) and (hf_right_tag is None)
    history = hf_right_tag is not None and 512 <= m <= 1024 and (512 <= n <= 1024) and (k >= 4 * max(m, n))
    key = (left.shape, right.shape, bool(leg_transport))
    if not (thin_wide or history) or (key in _KX_AVOID_SHAPES and (not history)) or (m, k, n) in PARAMS['si_ns_opcode_neutral_shapes'] or (int(KERNEL_CONFIG.get('kw_product_orientation', 0)) == 3):
        return _KX_GENERIC_PARENT_FAST(*_kx2_call_args, **_kx2_call_kwargs)
    reference = _kx_reference_route(m, k, n)
    best = None
    if reference is not None:
        (parent_cost, parent_requests, direct, parent_kind, parent_schemes) = reference
        for model in _KX_NS_MODELS:
            (cost, requests, elements, output) = _kx_route_price(m, k, n, model)
            if requests > parent_requests or elements > int(PARAMS['kx_route_max_elements']) or output > 350000000 or (parent_cost - cost < int(PARAMS['kx_route_min_saving'])):
                continue
            if best is None or cost < best[0]:
                best = (cost, model)
    if best is not None:
        if hf_right_tag is not None and parent_kind == (2, 2, 2):
            prior = _HF_RIGHT_CACHE_CONTEXT[0]
            _HF_RIGHT_CACHE_CONTEXT[0] = {'tag': hf_right_tag, 'right': right, 'allow': True}
            try:
                cache_key = hf_right_cache_key(right, parent_schemes)
                cached = cache_key is not None and cache_key in _HF_RIGHT_CACHE
            finally:
                _HF_RIGHT_CACHE_CONTEXT[0] = prior
            if cached:
                return _KX_GENERIC_PARENT_FAST(*_kx2_call_args, **_kx2_call_kwargs)
        if direct is not None:
            _kz_r40_route(m, k, n)
        (kind, schemes, coefficients, requests, funcs, scale) = best[1]
        return _SI115_NS_UNTRANSPOSED_PADDED(left, right, (kind, coefficients[3] // 7 ** len(schemes), funcs, schemes, scale))
    return _KX_GENERIC_PARENT_FAST(*_kx2_call_args, **_kx2_call_kwargs)



def _kx_donor_fast_matmul(*_kx2_call_args, **_kx2_call_kwargs):
    if len(_kx2_call_args) < 2 or len(_kx2_call_args) > 4 or (not _kx2_call_kwargs.keys() <= _OPS5_WRAPPER_KEYS) or (len(_kx2_call_args) > 2 and 'leg_transport' in _kx2_call_kwargs) or (len(_kx2_call_args) > 3 and 'hf_right_tag' in _kx2_call_kwargs):
        return _KX_DONOR_PARENT_FAST(*_kx2_call_args, **_kx2_call_kwargs)
    (left, right) = _kx2_call_args[:2]
    _ops3_left_shape = left.shape
    _ops3_right_shape = right.shape
    _ops3_left_rank = len(_ops3_left_shape)
    _ops3_right_rank = len(_ops3_right_shape)
    leg_transport = _kx2_call_kwargs.get('leg_transport', _kx2_call_args[2] if len(_kx2_call_args) > 2 else False)
    hf_right_tag = _kx2_call_kwargs.get('hf_right_tag', _kx2_call_args[3] if len(_kx2_call_args) > 3 else None)
    if _ops3_left_rank == 2 and _ops3_right_rank == 2:
        (m, k, n) = (_ops3_left_shape[0], _ops3_left_shape[1], _ops3_right_shape[1])
        mask = int(PARAMS['kx_route_donor_protect'])
        protected = min(m, n) >= 512 and (mask & 1 and m == n and (k == 4 * m) or (mask & 2 and m == k and (n == 4 * m)) or (mask & 4 and m == k and (n == 8 * m)))
        if protected:
            return _KX_DONOR_PARENT_FAST(*_kx2_call_args, **_kx2_call_kwargs)
    key = (_ops3_left_shape, _ops3_right_shape, bool(leg_transport))
    if not _kx_donor_KE_PARENT_SCOPE[0] and key not in _kx_donor_KE_PRUNED_SHAPES:
        key = (_ops3_left_shape, _ops3_right_shape, bool(leg_transport))
        if key in _kx_donor_NS_ROUTES:
            if str(left.dtype) == 'float32' and str(right.dtype) == 'float32':
                key = (_ops3_left_shape, _ops3_right_shape, bool(leg_transport))
                spec = _kx_donor_NS_ROUTES.get(key)
                if spec is not None:
                    if _ops3_left_rank == 2 and _ops3_right_rank == 2:
                        before = tuple(_KZ_R40_TAKEN)
                        parent_top = _kz_r40_route(int(_ops3_left_shape[0]), int(_ops3_left_shape[1]), int(_ops3_right_shape[1]))
                        if parent_top is not None and key in _kx_donor_NS_NO_R40:
                            _KZ_R40_TAKEN[:] = before
                            return _kx_donor_NS_PARENT_FAST_MATMUL(*_kx2_call_args, **_kx2_call_kwargs)
                        if parent_top is None:
                            descriptor = _kx_donor_NS_PARENT_KZ.get(key)
                            if descriptor is not None:
                                (ls, rs, parent_schemes) = descriptor
                                _kz_use_r48_root(SimpleNamespace(shape=ls, dtype=left.dtype), SimpleNamespace(shape=rs, dtype=right.dtype), parent_schemes)
                    return _kx_donor_ns_padded(left, right, spec)
            return _kx_donor_NS_PARENT_FAST_MATMUL(*_kx2_call_args, **_kx2_call_kwargs)
        if hf_right_tag is not None:
            if str(left.dtype) == 'float32' and str(right.dtype) == 'float32':
                key = (_ops3_left_shape, _ops3_right_shape, bool(leg_transport))
                spec = _kx_donor_NS_ROUTES.get(key)
                if spec is not None:
                    if _ops3_left_rank == 2 and _ops3_right_rank == 2:
                        before = tuple(_KZ_R40_TAKEN)
                        parent_top = _kz_r40_route(int(_ops3_left_shape[0]), int(_ops3_left_shape[1]), int(_ops3_right_shape[1]))
                        if parent_top is not None and key in _kx_donor_NS_NO_R40:
                            _KZ_R40_TAKEN[:] = before
                            return _kx_donor_NS_PARENT_FAST_MATMUL(*_kx2_call_args, **_kx2_call_kwargs)
                        if parent_top is None:
                            descriptor = _kx_donor_NS_PARENT_KZ.get(key)
                            if descriptor is not None:
                                (ls, rs, parent_schemes) = descriptor
                                _kz_use_r48_root(SimpleNamespace(shape=ls, dtype=left.dtype), SimpleNamespace(shape=rs, dtype=right.dtype), parent_schemes)
