@_ops3_lru_cache(maxsize=512)
def _cmp_product_selectors(runs):
    result = []
    for (first, last, low, high) in runs:
        left_key = (first, last, low, high)
        target = (slice(first, last), slice(None), slice(low, high))
        right_keys = []
        right_selectors = []
        for (broadcast_rows, broadcast_columns) in ((False, False), (True, False), (False, True), (True, True)):
            (begin, end) = (None, None) if broadcast_rows else (first, last)
            (start, stop) = (None, None) if broadcast_columns else (low, high)
            right_keys.append((begin, end, start, stop))
            right_selectors.append((slice(begin, end), slice(None), slice(start, stop)))
        result.append((first, last, low, high, left_key, target, tuple(right_keys), tuple(right_selectors)))
    return tuple(result)


def _cmp_store_view(views, key, entry):
    """Index real flat cache entries; no tensor operation is added or hidden."""
    views[key] = entry
    if isinstance(key, tuple) and len(key) == 5:
        index = views.get('_cmp_transient_view_keys')
        if index is None:
            index = {}
            views['_cmp_transient_view_keys'] = index
        index.setdefault(key[0], set()).add(key)

def _cmp_prune_product_views(views, values):
    if views is None:
        return 0
    index = views.get('_cmp_transient_view_keys', {})
    removed = 0
    for value in values:
        for key in index.pop(id(value), ()):
            if views.pop(key, None) is not None:
                removed += 1
        if views.pop(id(value), None) is not None:
            removed += 1
    return removed


from operator import itemgetter as _ops5_itemgetter
_ops5_domain_low = _ops5_itemgetter(0)
_ops5_domain_high = _ops5_itemgetter(1)
@_ops3_lru_cache(maxsize=1024)
def _ops5_interval_runs(domains, width, groups, threshold):
    count = len(domains)
    runs = []
    omitted = 0
    begin = 0
    while begin < count:
        (low, high) = domains[begin]
        if high <= low:
            omitted += width - high + low
            begin += 1
            continue
        stop = begin + 1
        while stop < count and domains[stop][1] > domains[stop][0]:
            stop += 1
        size = max(1, (stop - begin + groups - 1) // groups)
        for first in range(begin, stop, size):
            last = min(stop, first + size)
            window = domains[first:last]
            low = min(map(_ops5_domain_low, window))
            high = max(map(_ops5_domain_high, window))
            omitted += (last - first) * (width - high + low)
            if high > low:
                if runs and runs[-1][1] == first and (runs[-1][2:] == (low, high)):
                    runs[-1] = (runs[-1][0], last, low, high)
                else:
                    runs.append((first, last, low, high))
        begin = stop
    if threshold * omitted < count * width or ((count == 0 or width == 0) and all((low == 0 and high == width for (low, high) in domains))):
        return None
    return tuple(runs)

def _ops5_product_plan(state, indices, width, q_prefix=False, zero_first=False):
    groups = int(PARAMS['sym2_parent_hf2_support_groups'])
    threshold = int(PARAMS['sym2_parent_hf2_support_threshold'] if _W3K_HF2_SUPPORT_THRESHOLD is None else _W3K_HF2_SUPPORT_THRESHOLD)
    readout = state.runtime.readout
    contexts = readout.setdefault('ops5_parent_product_plans', {})
    key = (id(indices), width, groups, threshold)
    context = contexts.get(key)
    if context is None or context[0] is not indices:
        context = (indices, [False, False, False, False])
        contexts[key] = context
    slot = int(q_prefix) + 2 * int(zero_first)
    plan = context[1][slot]
    if plan is False:
        domains = []
        for index in indices:
            low = int(state.q_offsets[index]) if q_prefix else 0
            high = min(width, int(state.source_free_u[index].shape[0]))
            if zero_first and index == 0:
                low = high = 0
            domains.append((low, high))
        runs = _ops5_interval_runs(tuple(domains), width, groups, threshold)
        plan = None if runs is None else _cmp_product_selectors(runs)
        context[1][slot] = plan
    return plan

def _ops5_zero_first_empty(state, indices, width, q_prefix):
    for index in indices:
        if index == 0:
            continue
        low = int(state.q_offsets[index]) if q_prefix else 0
        if min(width, int(state.source_free_u[index].shape[0])) > low:
            return False
    return True

def _ops5_parent_product(state, indices, left, right, q_prefix=False, zero_first=False, fresh_right=False, _plan=False, _out=None, _cache_output=False):
    width = int(left.shape[2])
    readout = state.runtime.readout
    plan = _ops5_product_plan(state, indices, width, q_prefix, zero_first) if _plan is False else _plan
    if zero_first and plan is None and _ops5_zero_first_empty(state, indices, width, q_prefix):
        # exactF (set 2 Z2, ported to NEXTDIET's live source product): every source of the call has an empty support
        # (the zero_first source 0 alone: layer 1's star product, whose operand is the layer-0 star vertex w31 = +0). Its
        # product is exactly zero; every consumer takes None as that zero term and skips its add.
        return None
    if plan is None or left.dtype != right.dtype:
        return left * right
    if zero_first and (not plan):
        return None
    if _out is None:
        result = fnp.zeros(left.shape, dtype=left.dtype)
        if len(set(left.shape)) < len(left.shape):
            result = fnp.asarray(result)
    else:
        (result, _ops5_outputs) = _out
    views = readout.get('hf2_product_views')
    if views is None:
        views = {}
        readout['hf2_product_views'] = views
    left_rows = int(left.shape[0])
    (right_rows, right_columns) = (int(right.shape[0]), int(right.shape[2]))
    left_entry = views.get(id(left))
    if left_entry is None or left_entry[0] is not left:
        left_entry = (left, {})
        views[id(left)] = left_entry
    left_cache = left_entry[1]
    right_cache = None
    disposable_right = fresh_right and (right_rows != 1 or len(plan) == 1)
    right_kind = (1 if right_rows == 1 else 0) + (2 if right_columns == 1 else 0)
    _ops5_result_views = {} if _cache_output else None
    if _ops5_result_views is not None:
        views[id(result)] = (result, _ops5_result_views)
    _ops5_output_iter = iter(_ops5_outputs) if _out is not None else None
    for (first, last, low, high, left_key, target, right_keys, right_selectors) in plan:
        if first == 0 and last == left_rows and (low == 0) and (high == width):
            left_piece = left
        else:
            left_piece = left_cache.get(left_key)
            if left_piece is None:
                left_piece = left[target]
                left_cache[left_key] = left_piece
        if right is left:
            right_piece = left_piece
        else:
            right_key = right_keys[right_kind]
            (begin, end, column_begin, column_end) = right_key
            full_batch = begin in (None, 0) and end in (None, right_rows)
            full_columns = column_begin in (None, 0) and column_end in (None, right_columns)
            if full_batch and full_columns:
                right_piece = right
            elif disposable_right:
                right_piece = right[right_selectors[right_kind]]
            else:
                if right_cache is None:
                    right_entry = views.get(id(right))
                    if right_entry is None or right_entry[0] is not right:
                        right_entry = (right, {})
                        views[id(right)] = right_entry
                    right_cache = right_entry[1]
                right_piece = right_cache.get(right_key)
                if right_piece is None:
                    right_piece = right[right_selectors[right_kind]]
                    right_cache[right_key] = right_piece
        _ops5_target_view = result[target] if _ops5_output_iter is None else next(_ops5_output_iter)
        if _ops5_result_views is not None:
            _ops5_result_views[left_key] = _ops5_target_view
        fnp.multiply(left_piece, right_piece, out=_ops5_target_view)
    return result

def _sym2_parent_hf2_source_product(state, indices, left, right, q_prefix=False, zero_first=False):
    return _ops5_parent_product(state, indices, left, right, q_prefix, zero_first)


def _ops5_dense_yz(diagonal, remainder, mixed, repeated):
    _ops5_pub_add = fnp.add
    shape = tuple(diagonal.shape)
    if diagonal.dtype == 'float32' and all((tuple(value.shape) == shape and value.dtype == 'float32' for value in (remainder, mixed, repeated))):
        _ops5_pub_add(diagonal, remainder, out=remainder)
        _ops5_pub_add(remainder, mixed, out=remainder)
        _ops5_pub_add(repeated, remainder, out=repeated)
        return (remainder, repeated)
    y = diagonal + remainder + mixed
    return (y, repeated + y)

