@_ops3_lru_cache(maxsize=64)
def _ops5_peel_top(kind):
    scaled = kind in _KP_R40_GRAPHS
    graphs = _KP_R40_GRAPHS[kind] if scaled else _KZ_R20_GRAPHS[kind]
    adds = tuple([sum([len(step[2]) for step in graph[0]]) + sum([node < 0 or node in graph[1][:j] for (j, node) in enumerate(graph[1])]) + extra for (graph, extra) in zip(graphs, (0, 0, 0) if scaled else _KZ_R20_PRICED_ROWS.get(kind, (0, 0, 0)))])
    top = (kind, len(graphs[0][1]), adds, (0, 0, 0))
    return (top, scaled)


def _ops5_square_bank(bank):
    return fnp.unstack(fnp.multiply(bank, bank), axis=0)


